11	/**
12	 * Game-server auto-update handlers.
13	 *
14	 * `gameUpdate` runs a best-effort, per-family update command over SSH against
15	 * the server's private IP (the worker can reach vmbr1). `gameUpdateSweep` finds
16	 * RUNNING game servers with `autoUpdate=true` and enqueues GAME_UPDATE jobs for
17	 * them — safe to call periodically (it de-dupes on in-flight jobs).
18	 *
19	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
20	 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
21	 */
22	
23	/** Steam dedicated-server app IDs for steamcmd-based families. */
24	const STEAM_APPID: Partial<Record<GameFamily, string>> = {
25	  valheim: "896660",
26	  rust: "258550",
27	  palworld: "2394010",
28	  cs2: "730",
29	};
30	
31	/** systemd service name candidates per family (first that exists wins). */
32	const SERVICE_HINT: Record<GameFamily, string> = {
33	  minecraft: "minecraft",
34	  valheim: "valheim",
35	  rust: "rust",
36	  palworld: "palworld",
37	  cs2: "cs2",
38	  terraria: "terraria",
39	};
