80	/** Run the per-family update command over SSH (sshpass + private IP). */
81	export async function gameUpdate(job: Job): Promise<void> {
82	  const server = await loadGameServer(job.serverId!);
83	  if (SANDBOX) {
84	    // Simulate a successful update — no SSH to the (non-existent) VM.
85	    await notify(
86	      server.userId,
87	      `${server.osTemplate.name} updated on ${server.hostname}`,
88	      "The latest server update was applied (sandbox).",
89	      `/dashboard/servers/${server.id}`
90	    );
91	    return;
92	  }
93	  const family = server.osTemplate.family as GameFamily;
94	  if (!GAME_FAMILIES.includes(family)) {
95	    throw new Error(`game update: ${server.hostname} is not a game server`);
96	  }
97	  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
98	  const password = serverRootPassword(server);
99	  if (!server.ipAddress || !password) {
100	    throw new Error("game update: server has no IP/password yet");
101	  }
102	
103	  const remote = updateCommand(family);
104	  try {
105	    await execFileP(
106	      "sshpass",
107	      [
108	        "-p",
109	        password,
110	        "ssh",
111	        "-o",
112	        "StrictHostKeyChecking=no",
113	        "-o",
114	        "UserKnownHostsFile=/dev/null",
115	        "-o",
116	        "ConnectTimeout=15",
117	        `root@${server.ipAddress}`,
118	        remote,
119	      ],
120	      { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
121	    );
122	  } catch (e: any) {
123	    // execFile embeds the full argv — including `-p <rootPassword>` — into its
124	    // error message/cmd. Rethrow a sanitized error so the password can never be
125	    // stored in Job.error (the worker also redacts as a second line of defense).
126	    const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
127	    const detail = scrub(String(e?.stderr || e?.message || e));
128	    throw new Error(`game update failed: ${detail}`);
129	  }
130	
131	  await notify(
132	    server.userId,
133	    `${server.osTemplate.name} updated on ${server.hostname}`,
134	    "The latest server update was applied and the service was restarted.",
135	    `/dashboard/servers/${server.id}`
136	  );
137	}
