139	/**
140	 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
141	 * auto-update and has no job already in flight. Idempotent / safe to call on a
142	 * timer. Returns nothing; logs a summary.
143	 */
144	export async function gameUpdateSweep(): Promise<void> {
145	  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
146	  const candidates = await db.server.findMany({
147	    where: {
148	      status: "RUNNING",
149	      autoUpdate: true,
150	      osTemplate: { family: { in: [...GAME_FAMILIES] } },
151	    },
152	    select: { id: true, hostname: true },
153	  });
154	  if (candidates.length === 0) return;
155	
156	  let enqueued = 0;
157	  for (const s of candidates) {
158	    const inflight = await db.job.count({
159	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
160	    });
161	    if (inflight > 0) continue;
162	    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
163	    enqueued++;
164	  }
165	  if (enqueued > 0) console.log(`[game-update] sweep enqueued ${enqueued} update job(s)`);
166	}
