/**
 * Create the app's database + user with the generated password (STDIN only),
 * then PROVE that credential works by connecting with it. The customer is shown
 * this password once and types it into the app's setup wizard; "the CREATE
 * statement exited 0" is not evidence that it will log in.
 */
async function provisionDb(
  conn: Client,
  engine: string,
  name: string,
  user: string,
  password: string
): Promise<void> {
  assertIdent(name, "database name");
  assertIdent(user, "database user");
  assertInertSecret(password, "database password");

  if (engine === "mysql") {
    // No IF NOT EXISTS: assertNothingToOverwrite has already established that
    // neither exists, so a collision here is a real error and must surface.
    const sql =
      `CREATE DATABASE \`${name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
      `CREATE USER '${user}'@'localhost' IDENTIFIED BY '${password}';\n` +
      `GRANT ALL PRIVILEGES ON \`${name}\`.* TO '${user}'@'localhost';\n` +
      `FLUSH PRIVILEGES;\n`;
    const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
    if (r.code !== 0) throw new Error(`database setup failed: ${why(r)}`);

    // Log in AS the customer's user. The password reaches mysql through a 0600
    // defaults file written by the same shell that deletes it — never argv.
    const check = await execInput(
      conn,
      `umask 077; f=$(mktemp) && cat > "$f" && ` +
        `mysql --defaults-extra-file="$f" --protocol=socket -N -B -e 'SELECT 1' ${shellQuote(name)} >/dev/null 2>&1; ` +
        `rc=$?; rm -f "$f"; exit $rc`,
      `[client]\nuser=${user}\npassword=${password}\n`,
      SETUP_TIMEOUT_MS
    );
    if (check.code !== 0)
      throw new Error(
        `the generated database credentials did not work when tested — not handing the customer a password that does not log in.`
      );
  } else if (engine === "postgres") {
    const sql = `CREATE ROLE "${user}" LOGIN PASSWORD '${password}';\nCREATE DATABASE "${name}" OWNER "${user}";\n`;
    const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
    if (r.code !== 0) throw new Error(`database setup failed: ${why(r)}`);
    // No login test: nothing in the catalogue provisions PostgreSQL, so rather
    // than ship an untested probe we leave the gap visible here.
  } else {
    throw new Error(`Unsupported database engine: ${engine}`);
  }
}

