/* ------------------------------------------------------------------ *
 * 9. Do not hand the customer action items the machine already did
 *
 * Distro units live in /lib/systemd/system, so pulling
 * /etc/systemd/system/<svc>.service off the source ALWAYS fails for them. The
 * engine then pushed one identical "re-enable manually" line per unit. In the
 * rehearsal that was seven of twenty-two needsAttention entries — containerd,
 * docker, exim4, mariadb, nginx, qemu-guest-agent, serial-getty@ttyS0 — telling
 * the customer to hand-re-enable software the target had already installed and
 * was already RUNNING, in the same summary that said `nginx restarted`. The two
 * entries that were real were buried in it.
 * ------------------------------------------------------------------ */

test("a service this server already runs is not an action item", () => {
  const v = distroUnitVerdict({ svc: "nginx", presentHere: true, activeHere: true });
  assert.equal(v.status, "running", "verified up on the target — not 'copied, needs attention'");
  assert.match(v.detail, /already running/);
  assert.ok(!/re-enable manually/.test(v.detail));
});

test("installed but stopped is reported honestly, with the command", () => {
  const v = distroUnitVerdict({ svc: "exim4", presentHere: true, activeHere: false });
  assert.equal(v.status, "copied");
  assert.match(v.detail, /not running/);
  assert.match(v.detail, /systemctl enable --now exim4/, "every blocker carries a fix the customer can run");
});

test("a service that is genuinely absent here says so plainly, and is not softened", () => {
  // The case the old blanket message was actually right about — it must survive,
  // and it must say the thing that matters: nothing here provides this.
  const v = distroUnitVerdict({ svc: "redis-server", presentHere: false, activeHere: false });
  assert.equal(v.status, "copied");
  assert.match(v.detail, /was NOT migrated/);
  assert.match(v.detail, /does not have redis-server at all/);
  assert.match(v.detail, /apt-get install -y redis-server/);
});

