export async function listBackupsOn(client: any, vmid: number): Promise<StorageBackupEntry[]> {
  const content: StorageBackupEntry[] = await client.get(
    `/nodes/${client.node}/storage/backup/content`,
    { content: "backup" }
  );
  return content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
