/**
 * Create one backup and PROVE it exists before saying so.
 *
 * INCIDENT H4 (2026-07-26 rehearsal): this handler gated only the vzdump task's
 * exit status — it never checked that an archive was written, had no failure
 * notification, and `Server.lastAutoBackup` was stamped by the SWEEP at enqueue
 * time. A customer could read "Last automatic backup: today" every night for a
 * month with nothing in storage, and find out at restore time.
 *
 * Now: snapshot the archive list before the run, re-read it after, and require a
 * volid that was not there and is not empty (`freshBackupProof`). Only that
 * writes `lastAutoBackup`. A failure notifies the customer with the reason and a
 * command, rather than leaving a stale-but-cheerful timestamp behind.
 */
async function backupCreate(job: Job) {
  const server = await loadServer(job);
  if (SANDBOX) {
    await sandboxAnimateJob(job.id, [
      { pct: 5, step: "Starting" },
      { pct: 25, step: "Creating archive… 25%" },
      { pct: 55, step: "Creating archive… 55%" },
      { pct: 80, step: "Creating archive… 80%" },
      { pct: 95, step: "Finalizing" },
      { pct: 100, step: "Backup complete" },
    ]);
    // Deliberately NOT stamping lastAutoBackup here: no archive exists, and the
    // column means "a backup was observed in storage".
    await notify(
      server.userId,
      `Backup simulated (sandbox) for ${server.hostname}`,
      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  if (server.vmid == null) {
    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
  }
  const vmid = server.vmid;

  try {
    await reportJobProgress(job.id, 2, "Starting");
    const { conn } = await nodeFor(server);

    // Snapshot what already exists. Membership of this set — not a timestamp
    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
    // off the hypervisor and our window would come off the worker's clock.
    const before = await listBackupsOn(conn, vmid);

    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
      vmid,
      storage: "backup",
      mode: "snapshot",
      compress: "zstd",
    });
    await waitForTaskProgress(
      conn,
      upid,
      (progress, step) => reportJobProgress(job.id, progress, step),
      { timeoutMs: 3_600_000, phase: "backup" }
    );

    await reportJobProgress(job.id, 96, "Verifying archive");
    const after = await listBackupsOn(conn, vmid);
    const proof = freshBackupProof({ vmid, before, after });
    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);

    await reportJobProgress(job.id, 100, "Backup complete");

    // Retention: keep only the latest few backups for this server; prune the rest.
    try {
      const pruned = await pruneBackups(conn, vmid, CUSTOMER_BACKUP_KEEP);
      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${CUSTOMER_BACKUP_KEEP})`);
    } catch (e) {
      console.error(`[backup] prune failed for vmid ${vmid}`, e);
    }

    // The ONLY writer of lastAutoBackup, and only on proof.
    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });

    await notify(
      server.userId,
      `Backup completed for ${server.hostname}`,
      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
      `/dashboard/servers/${server.id}`
    );
  } catch (e: any) {
    // Tell the customer it broke. Only on the final attempt, so the worker's
    // three retries do not produce three notifications for one bad night.
    if (job.attempts >= MAX_ATTEMPTS) {
      await notify(
        server.userId,
        `Backup FAILED for ${server.hostname}`,
        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
          `Your last verified backup (if any) is shown under Backups.`,
        `/dashboard/servers/${server.id}`
      );
    }
    throw e;
  }
}

