/**
 * Backup PROOF rules — the pure decision logic that stands between "the vzdump
 * task returned" and telling a customer they have a restore point.
 *
 * INCIDENT (customer-journey rehearsal 2026-07-26, finding H4): `lastAutoBackup`
 * was stamped at the moment the BACKUP_CREATE job row was ENQUEUED, and written
 * nowhere else. So "Last automatic backup: 2026-07-26 04:00 UTC" only ever meant
 * *a row was created*. vzdump could have failed every night for a month with no
 * alert, no failure notification, and the schedule marked satisfied — so the
 * retry was a full interval away and the customer found out at restore time, the
 * one moment it cannot be fixed. The deploy wizard SELLS this at the point of
 * sale ("Daily auto-backups · Nightly snapshots to separate storage for easy
 * restore").
 *
 * The rules now:
 *
 *   - `Server.lastAutoBackup` is a PROOF timestamp. It is written in exactly one
 *     place — `backupCreate` in worker/index.ts — after a storage-content read
 *     shows an archive for this VMID that was NOT there before the run and has
 *     size > 0. An exit code from the vzdump task is not evidence.
 *   - The sweep's anti-pile-up anchor is the last ATTEMPT, read from the Job
 *     table. That is a fact we can observe without claiming anything about the
 *     outcome.
 *   - Absence is rendered, not hidden: `backupScheduleHealth` is the single
 *     source of the sentence the customer reads under "Scheduled backups".
 *
 * Deterministic and dependency-free on purpose: no Prisma, no Proxmox, no clock
 * (every entry point takes `now`). Covered by test/backup-proof.test.ts.
 */

// ---------------------------------------------------------------------------
// Proof
// ---------------------------------------------------------------------------

/** The subset of a Proxmox storage-content row this module reasons about. */
export type BackupArchive = {
  volid?: string;
  vmid?: number;
  size?: number;
  ctime?: number;
};

export type BackupProof =
  | { proven: true; volid: string; sizeBytes: number }
  | { proven: false; reason: string };

/** Human-sized bytes for notification/log copy. */
export function humanBytes(n: number): string {
  if (!Number.isFinite(n) || n < 0) return "unknown size";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let v = n;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${i === 0 ? v : v.toFixed(1)} ${units[i]}`;
}

/**
 * Did THIS run demonstrably write a backup?
 *
 * Evidence is a volid present in `after` that was absent from `before`, carrying
 * a non-zero size. Set membership rather than a timestamp comparison on purpose:
 * `ctime` comes off the hypervisor and any window we computed would come off the
 * worker's clock, and skew between the two is exactly the kind of thing that
 * turns a proof back into a guess. A volid that was not there and now is cannot
 * be explained away by a clock.
 *
 * Every failure returns the reason AND the command an operator can run, because
 * "backup failed" with no next step is barely better than the silence it
 * replaced.
 */
export function freshBackupProof(opts: {
  vmid: number;
  before: readonly BackupArchive[];
  after: readonly BackupArchive[];
}): BackupProof {
  const { vmid } = opts;
  const check = `Check it yourself with: pvesm list backup --vmid ${vmid}`;
  const seen = new Set<string>();
  for (const b of opts.before) {
    if (b.vmid === vmid && typeof b.volid === "string") seen.add(b.volid);
  }

  const fresh = opts.after.filter(
    (b) => b.vmid === vmid && typeof b.volid === "string" && !seen.has(b.volid)
  );

  if (fresh.length === 0) {
    return {
      proven: false,
      reason:
        `the vzdump task finished but no new archive for VMID ${vmid} appeared in the ` +
        `"backup" storage, so nothing was written and there is no restore point from this run. ` +
        check,
    };
  }

  // Prefer the largest new archive: if a run somehow left a truncated stub beside
  // a good one, the good one is the honest answer.
  const sized = fresh
    .filter((b) => typeof b.size === "number" && Number.isFinite(b.size))
    .sort((a, b) => (b.size ?? 0) - (a.size ?? 0));

  if (sized.length === 0) {
    return {
      proven: false,
      reason:
        `a new archive for VMID ${vmid} appeared (${fresh[0].volid}) but the storage listing ` +
        `reported no size for it, so we cannot confirm it contains anything. ` +
        `Not recording a backup we cannot prove. ` +
        check,
    };
  }

  const best = sized[0];
  if ((best.size ?? 0) <= 0) {
    return {
      proven: false,
      reason:
        `a new archive for VMID ${vmid} appeared (${best.volid}) but it is 0 bytes — ` +
        `an empty file is not a backup and would fail at restore time. ` +
        check,
    };
  }

  return { proven: true, volid: best.volid!, sizeBytes: best.size! };
}

// ---------------------------------------------------------------------------
// Scheduling
// ---------------------------------------------------------------------------

/**
 * Is another automatic backup due?
 *
 * Anchored on the last ATTEMPT, never on the last SUCCESS. Anchoring on success
 * looks more correct and is a trap: a server whose backups always fail has no
 * success to anchor to, so it would be "due" on every 15-minute sweep pass
 * forever — hammering a sick VM and burying the rest of the fleet's queue behind
 * it. The attempt is a fact; the outcome is what we refuse to assume.
 */
export function isAutoBackupDue(opts: {
  now: number;
  intervalHours: number | null;
  lastAttemptAt: Date | null;
}): boolean {
  const hours = opts.intervalHours ?? 0;
  if (!(hours > 0)) return false;
  if (!opts.lastAttemptAt) return true;
  return opts.now >= opts.lastAttemptAt.getTime() + hours * 60 * 60_000;
}

export type BackupHealthState = "off" | "ok" | "pending" | "never" | "stale" | "failing";
export type BackupHealth = { state: BackupHealthState; detail: string };

/** How many intervals may elapse with no verified backup before we call it stale. */
export const STALE_INTERVAL_MULTIPLE = 2;

function stamp(d: Date): string {
  return d.toISOString().slice(0, 16).replace("T", " ") + " UTC";
}

/**
 * The one sentence the customer reads under "Scheduled backups", and the same
 * one the sweep logs for the operator. It must never imply a restore point that
 * was not proved.
 *
 * `lastVerifiedAt` is `Server.lastAutoBackup`, which since H4 means "an archive
 * was observed in storage at this time" — not "a job was queued at this time".
 */
export function backupScheduleHealth(opts: {
  now: number;
  autoBackup: boolean;
  intervalHours: number | null;
  lastVerifiedAt: Date | null;
  lastAttempt: { at: Date; status: string } | null;
}): BackupHealth {
  const hours = opts.intervalHours ?? 0;
  if (!opts.autoBackup || !(hours > 0)) {
    return { state: "off", detail: "Scheduled backups are off for this server." };
  }

  const verified = opts.lastVerifiedAt;
  const verifiedLine = verified
    ? `The most recent backup we can prove exists is from ${stamp(verified)}.`
    : "No automatic backup has ever been verified for this server, so the schedule has produced no restore point.";

  // Ordered by what the customer stands to lose, not by tidiness: a failing
  // schedule outranks a stale one, which outranks "we have never seen one".
  if (opts.lastAttempt?.status === "FAILED") {
    return {
      state: "failing",
      detail:
        `The last automatic backup attempt (${stamp(opts.lastAttempt.at)}) FAILED. ` +
        `${verifiedLine} Open a ticket if this repeats — do not assume tonight's run will fix it.`,
    };
  }

  if (!verified) {
    if (!opts.lastAttempt) {
      return {
        state: "pending",
        detail: "No automatic backup has run yet — the first one is queued by the next sweep.",
      };
    }
    return {
      state: "never",
      detail:
        `Automatic backups have been attempted since ${stamp(opts.lastAttempt.at)}, but none has ` +
        "been verified to exist in storage. Do not rely on having a restore point.",
    };
  }

  const overdueAfter = verified.getTime() + hours * 60 * 60_000 * STALE_INTERVAL_MULTIPLE;
  if (opts.now > overdueAfter) {
    return {
      state: "stale",
      detail:
        `${verifiedLine} That is more than ${STALE_INTERVAL_MULTIPLE} backup intervals ago, so the ` +
        "schedule is not keeping up. Treat anything newer than that as unprotected.",
    };
  }

  return { state: "ok", detail: `Last verified backup: ${stamp(verified)} (confirmed present in storage).` };
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { backupScheduleHealth, isAutoBackupDue } from "../lib/backup-verify";

/**
 * Scheduled-backup sweep.
 *
 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
 * (`autoBackup=true`) whose last backup ATTEMPT is older than their configured
 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
 * each — de-duping on any in-flight job so it's safe to call on a timer.
 *
 * It deliberately writes NOTHING to `Server.lastAutoBackup`. That used to be
 * stamped right here, at enqueue time, which is how a customer could read "Last
 * automatic backup: today" every night while vzdump silently failed every night
 * (incident H4). The column now means "an archive was observed in storage", and
 * `backupCreate` in worker/index.ts is its only writer. All the decision logic
 * lives in lib/backup-verify.ts so it can be tested without a DB or a clock.
 *
 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
 *
 *   import { scheduledBackupSweep } from "./backup-schedule";
 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
 *     lastBackupSweep = Date.now();
 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
 *   }
 */
export async function scheduledBackupSweep(): Promise<void> {
  if (SANDBOX) return; // no real backups run in the sandbox
  const now = Date.now();

  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoBackup: true,
      backupIntervalHours: { not: null },
    },
    select: {
      id: true,
      hostname: true,
      backupIntervalHours: true,
      lastAutoBackup: true,
    },
  });
  if (candidates.length === 0) return;

  // One row per server: the most recent BACKUP_CREATE job, whatever its outcome.
  // This is the attempt anchor — see `isAutoBackupDue` for why anchoring on
  // success instead would hammer a server whose backups always fail.
  const lastAttempts = await db.job.findMany({
    where: { serverId: { in: candidates.map((s) => s.id) }, type: "BACKUP_CREATE" },
    orderBy: { createdAt: "desc" },
    distinct: ["serverId"],
    select: { serverId: true, createdAt: true, status: true },
  });
  const attemptBy = new Map(lastAttempts.map((j) => [j.serverId as string, j]));

  let enqueued = 0;
  for (const s of candidates) {
    const attempt = attemptBy.get(s.id) ?? null;
    const due = isAutoBackupDue({
      now,
      intervalHours: s.backupIntervalHours,
      lastAttemptAt: attempt?.createdAt ?? null,
    });
    if (!due) continue;

    // Respect the one-in-flight-job-per-server invariant.
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;

    // Surface a schedule that is quietly not producing backups. The customer's
    // own notification comes from the failing job; this is the operator's copy,
    // and it is the signal that used to be invisible.
    const health = backupScheduleHealth({
      now,
      autoBackup: true,
      intervalHours: s.backupIntervalHours,
      lastVerifiedAt: s.lastAutoBackup,
      lastAttempt: attempt ? { at: attempt.createdAt, status: attempt.status } : null,
    });
    if (health.state === "never" || health.state === "stale" || health.state === "failing") {
      console.error(`[backup-schedule] ${s.hostname}: ${health.state} — ${health.detail}`);
    }

    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id, payload: { auto: true } } });
    enqueued++;
  }

  if (enqueued > 0) console.log(`[backup-schedule] sweep enqueued ${enqueued} backup job(s)`);
}

/**
 * Port-forward (DNAT) rule planning, reconciliation and PROOF.
 *
 * INCIDENT (customer-journey rehearsal 2026-07-26, finding H5): `syncPortForwards`
 * opened with an unconditional `iptables -t nat -F NXEON_FWD` and then rebuilt the
 * whole chain in a loop with no try/catch, no rollback and no read-back. `exec`
 * there is `promisify(execFile)`, so ONE failed `-A` rejected and aborted the
 * loop — every server after that point was left with no DNAT rule at all. The job
 * still went DONE, because DONE meant "the last `iptables -A` exited 0". The
 * result was a fleet-wide SSH blackhole with no notification and a dashboard
 * still showing everyone's port. Worse, `remove()` calls the sync AFTER deleting
 * the server row, so the throw re-queued DELETE, which then died on "Server not
 * found" and never retried the sync.
 *
 * WHAT MID-FLUSH LOOKS LIKE, and why this module does not flush:
 *
 *   A flush is an instant, total outage for every customer on the box. Everything
 *   between the `-F` and the last successful `-A` is a window in which live SSH
 *   sessions keep working (conntrack) but every NEW connection is dropped. If the
 *   rebuild dies halfway — a malformed IP, an ENOENT on the iptables binary, the
 *   worker being restarted, the DB query returning a partial fleet — the window
 *   never closes and nothing notices.
 *
 *   So there is no flush. We READ the chain, DIFF it against what the database
 *   says should be there, and apply only the difference. A rule that is already
 *   correct is never removed, so no failure anywhere in this module can take down
 *   a customer who was working before it ran. Then we read the chain BACK and
 *   compare it to the intent; anything missing is raised loudly with the exact
 *   command an operator can run. "The last iptables call exited 0" is not proof
 *   that the ruleset is right, and is no longer accepted as such.
 *
 * Everything here is pure except `reconcileNatChain`, which is driven through the
 * `NatHost` seam so test/nat-sync.test.ts can exercise it against an in-memory
 * fake chain with no iptables, no root and no network.
 */

export type NatRule = {
  /** "tcp" | "udp" */
  proto: string;
  /** Public port on the host. */
  dport: number;
  /** Guest IP the packet is rewritten to. */
  destIp: string;
  /** Guest port the packet is rewritten to. */
  destPort: number;
};

/** One server's forwarding requirements, as read from the database. */
export type ForwardSource = {
  serverId: string;
  hostname: string;
  ipAddress: string | null;
  sshPort: number | null;
  portForwards: { protocol: string; publicPort: number; guestPort: number }[];
};

export type NatConflict = { proto: string; dport: number; winner: string; losers: string[] };
export type NatRejection = { hostname: string; reason: string };

export type NatIntent = {
  /** Exactly what the chain should contain, in a stable order. */
  rules: NatRule[];
  /** Two servers claiming the same public port. The loser's rule is NOT installed. */
  conflicts: NatConflict[];
  /** Rows we refused to turn into a rule because a field was not a valid IP/port/protocol. */
  rejected: NatRejection[];
};

const IPV4 = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;

function validPort(n: unknown): n is number {
  return typeof n === "number" && Number.isInteger(n) && n >= 1 && n <= 65535;
}

/**
 * Turn the fleet into the exact DNAT ruleset the chain should hold.
 *
 * Two things this refuses to do quietly:
 *
 *  1. Install a rule built from a field that is not a valid IPv4 address, port or
 *     protocol. `execFile` with an argv array is already injection-safe, but a
 *     malformed value produces an iptables error mid-run, which under the old
 *     flush-and-rebuild is what aborted the loop and blackholed everyone after
 *     it. Rejected rows are reported, not silently skipped.
 *  2. Install two rules claiming the same protocol/public port. iptables is
 *     first-match, so a duplicate silently sends one customer's traffic to
 *     another customer's VM. The first claimant (stable order) wins and the
 *     collision is reported so somebody can fix the allocation.
 */
export function planNatRules(servers: readonly ForwardSource[]): NatIntent {
  const rules: NatRule[] = [];
  const conflicts: NatConflict[] = [];
  const rejected: NatRejection[] = [];
  const claimed = new Map<string, { hostname: string; index: number }>();

  const claim = (r: NatRule, hostname: string) => {
    const key = `${r.proto}/${r.dport}`;
    const prior = claimed.get(key);
    if (prior) {
      const c = conflicts.find((x) => x.proto === r.proto && x.dport === r.dport);
      if (c) c.losers.push(hostname);
      else conflicts.push({ proto: r.proto, dport: r.dport, winner: prior.hostname, losers: [hostname] });
      return;
    }
    claimed.set(key, { hostname, index: rules.length });
    rules.push(r);
  };

  // Stable order: sorted by hostname, then by public port. iptables is
  // first-match on distinct ports so order does not affect behaviour, but a
  // deterministic order makes the diff, the logs and the tests readable.
  const ordered = [...servers].sort((a, b) => a.hostname.localeCompare(b.hostname));

  for (const s of ordered) {
    if (!s.ipAddress || !IPV4.test(s.ipAddress)) {
      rejected.push({ hostname: s.hostname, reason: `private IP ${JSON.stringify(s.ipAddress)} is not a valid IPv4 address` });
      continue;
    }
    if (!validPort(s.sshPort)) {
      rejected.push({ hostname: s.hostname, reason: `SSH port ${JSON.stringify(s.sshPort)} is not a valid port` });
    } else {
      claim({ proto: "tcp", dport: s.sshPort, destIp: s.ipAddress, destPort: 22 }, s.hostname);
    }

    for (const f of [...s.portForwards].sort((a, b) => a.publicPort - b.publicPort)) {
      const proto = String(f.protocol ?? "").toLowerCase();
      if (proto !== "tcp" && proto !== "udp") {
        rejected.push({ hostname: s.hostname, reason: `port forward protocol ${JSON.stringify(f.protocol)} is not tcp or udp` });
        continue;
      }
      if (!validPort(f.publicPort) || !validPort(f.guestPort)) {
        rejected.push({
          hostname: s.hostname,
          reason: `port forward ${JSON.stringify(f.publicPort)}->${JSON.stringify(f.guestPort)} has an out-of-range port`,
        });
        continue;
      }
      claim({ proto, dport: f.publicPort, destIp: s.ipAddress, destPort: f.guestPort }, s.hostname);
    }
  }

  return { rules, conflicts, rejected };
}

/** The identity of a rule for set operations — everything that makes it distinct. */
export function ruleKey(r: NatRule): string {
  return `${r.proto}/${r.dport}->${r.destIp}:${r.destPort}`;
}

/** Human-readable, and close enough to the real command to paste after `iptables -t nat -A NXEON_FWD`. */
export function ruleText(r: NatRule): string {
  return `-p ${r.proto} --dport ${r.dport} -j DNAT --to-destination ${r.destIp}:${r.destPort}`;
}

/** The argv fragment shared by -A, -D and -C. */
export function ruleSpec(r: NatRule): string[] {
  return [
    "-p", r.proto,
    "--dport", String(r.dport),
    "-j", "DNAT",
    "--to-destination", `${r.destIp}:${r.destPort}`,
  ];
}

/**
 * Parse `iptables -t nat -S <chain>` back into rules.
 *
 * iptables normalises what it prints (it inserts `-m tcp`, and reorders some
 * options), so the output is NOT byte-comparable to what we passed to `-A`. It is
 * parsed rather than string-matched for exactly that reason.
 *
 * Anything in our chain we cannot parse is returned in `unparsed` and never
 * touched. Deleting a rule we do not understand is how you turn "a stray rule
 * exists" into "somebody's forwarding is gone", and we do not know enough to be
 * making that trade silently.
 */
export function parseChainRules(chain: string, sOutput: string): { rules: NatRule[]; unparsed: string[] } {
  const rules: NatRule[] = [];
  const unparsed: string[] = [];
  for (const raw of String(sOutput ?? "").split("\n")) {
    const line = raw.trim();
    if (!line) continue;
    if (!line.startsWith(`-A ${chain} `)) continue; // -N, and jumps in other chains
    const body = line.slice(`-A ${chain} `.length);
    const proto = /(?:^|\s)-p\s+(tcp|udp)(?:\s|$)/.exec(body)?.[1];
    const dport = /(?:^|\s)--dport\s+(\d{1,5})(?:\s|$)/.exec(body)?.[1];
    const dest = /(?:^|\s)--to-destination\s+(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})(?:\s|$)/.exec(body);
    const isDnat = /(?:^|\s)-j\s+DNAT(?:\s|$)/.test(body);
    if (!proto || !dport || !dest || !isDnat) {
      unparsed.push(line);
      continue;
    }
    const r: NatRule = { proto, dport: Number(dport), destIp: dest[1], destPort: Number(dest[2]) };
    if (!validPort(r.dport) || !validPort(r.destPort) || !IPV4.test(r.destIp)) {
      unparsed.push(line);
      continue;
    }
    rules.push(r);
  }
  return { rules, unparsed };
}

export type NatPlan = { toAdd: NatRule[]; toDelete: NatRule[] };

/**
 * What has to change to turn `actual` into `intended`.
 *
 * This is the whole point of the rewrite: a rule that is already correct appears
 * in neither list, so it is never removed and never re-added. There is no moment
 * at which a working customer's forwarding is absent from the kernel.
 */
export function natReconcilePlan(intended: readonly NatRule[], actual: readonly NatRule[]): NatPlan {
  const want = new Map(intended.map((r) => [ruleKey(r), r]));
  const have = new Map(actual.map((r) => [ruleKey(r), r]));
  const toAdd = [...want.entries()].filter(([k]) => !have.has(k)).map(([, r]) => r);
  const toDelete = [...have.entries()].filter(([k]) => !want.has(k)).map(([, r]) => r);
  return { toAdd, toDelete };
}

export type NatVerdict = { ok: boolean; missing: NatRule[]; extra: NatRule[] };

/**
 * Did the chain end up holding what we intended? Read back from the kernel, not
 * inferred from exit codes.
 */
export function verifyNatChain(intended: readonly NatRule[], actual: readonly NatRule[]): NatVerdict {
  const { toAdd: missing, toDelete: extra } = natReconcilePlan(intended, actual);
  return { ok: missing.length === 0 && extra.length === 0, missing, extra };
}

/**
 * The failure sentence. Named, exported and tested because the whole defect class
 * is "a surface reported an outcome it did not verify" — the remedy is only worth
 * anything if what it says is specific enough to act on.
 */
export function natFailureMessage(opts: {
  chain: string;
  missing: readonly NatRule[];
  extra: readonly NatRule[];
  errors: readonly string[];
}): string {
  const parts: string[] = [];
  if (opts.missing.length) {
    parts.push(
      `${opts.missing.length} port-forward rule(s) are NOT in the ${opts.chain} chain after the sync, ` +
        `so that traffic is being dropped: ${opts.missing.slice(0, 8).map(ruleText).join("; ")}` +
        (opts.missing.length > 8 ? ` (+${opts.missing.length - 8} more)` : "")
    );
  }
  if (opts.extra.length) {
    parts.push(
      `${opts.extra.length} rule(s) that should have been removed are still present: ` +
        opts.extra.slice(0, 8).map(ruleText).join("; ")
    );
  }
  if (opts.errors.length) parts.push(`iptables reported: ${opts.errors.slice(0, 8).join(" | ")}`);
  parts.push(`Inspect the live chain with: iptables -t nat -S ${opts.chain}`);
  return parts.join(". ");
}

// ---------------------------------------------------------------------------
// The seam
// ---------------------------------------------------------------------------

/**
 * Everything `reconcileNatChain` needs from the host, as an interface rather than
 * a bare `execFile`.
 *
 * WHY: this function edits the live NAT table of a production box carrying paying
 * customers. Its decision ladder — what to delete, what to add, what counts as
 * proof afterwards, what to say when it does not hold — must be exercised
 * without touching a kernel, so the only implementation production ever uses
 * (`iptablesHost` in worker/network.ts) is matched by an in-memory fake in
 * test/nat-sync.test.ts.
 */
export type NatHost = {
  /** Create the chain and the PREROUTING jump if absent. Must be idempotent. */
  ensureChain: () => Promise<void>;
  /** Raw `iptables -t nat -S <chain>` output. */
  listChain: () => Promise<string>;
  addRule: (r: NatRule) => Promise<void>;
  deleteRule: (r: NatRule) => Promise<void>;
};

export type NatSyncResult = {
  added: number;
  deleted: number;
  /** Rules the chain is proven to hold. */
  verified: number;
  conflicts: NatConflict[];
  rejected: NatRejection[];
  /** Lines in our chain we could not parse; left alone, reported here. */
  unparsed: string[];
};

/**
 * Reconcile the chain to `intent` and PROVE the result, or throw saying exactly
 * what is broken.
 *
 * Failure handling is deliberately two-phase. Individual `-A`/`-D` errors are
 * COLLECTED rather than thrown, so one bad rule can no longer abandon every
 * server after it in the list — that was the H5 blackhole. Then the chain is read
 * back and compared to the intent, and only that comparison decides success. A
 * rule that failed to add but turns out to be present anyway (a concurrent sync)
 * is not an error; a rule that "added fine" but is not in the chain is.
 */
export async function reconcileNatChain(
  host: NatHost,
  chain: string,
  intent: NatIntent
): Promise<NatSyncResult> {
  await host.ensureChain();

  const current = parseChainRules(chain, await host.listChain());
  const plan = natReconcilePlan(intent.rules, current.rules);
  const errors: string[] = [];

  // Delete first: frees a public port that is being reassigned to another guest
  // in the same pass, which would otherwise be an unresolvable conflict.
  let deleted = 0;
  for (const r of plan.toDelete) {
    try {
      await host.deleteRule(r);
      deleted++;
    } catch (e: any) {
      errors.push(`delete ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
    }
  }

  let added = 0;
  for (const r of plan.toAdd) {
    try {
      await host.addRule(r);
      added++;
    } catch (e: any) {
      errors.push(`add ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
    }
  }

  // The proof. Not "every call exited 0" — what the kernel actually holds now.
  const final = parseChainRules(chain, await host.listChain());
  const verdict = verifyNatChain(intent.rules, final.rules);
  if (!verdict.ok) {
    throw new Error(
      natFailureMessage({ chain, missing: verdict.missing, extra: verdict.extra, errors })
    );
  }
  if (errors.length) {
    // Every intended rule is present and no stray remains, so forwarding is
    // correct — but something errored on the way and that is not nothing.
    console.warn(`[nat] ${chain} reconciled, but iptables errored on the way: ${errors.join(" | ")}`);
  }

  return {
    added,
    deleted,
    verified: final.rules.length,
    conflicts: intent.conflicts,
    rejected: intent.rejected,
    unparsed: final.unparsed,
  };
}

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "../lib/db";
import {
  planNatRules,
  reconcileNatChain,
  ruleSpec,
  type ForwardSource,
  type NatHost,
  type NatRule,
  type NatSyncResult,
} from "../lib/nat-rules";

const exec = promisify(execFile);

const CHAIN = process.env.NXEON_NAT_CHAIN ?? "NXEON_FWD";

async function iptables(args: string[]) {
  await exec("iptables", args);
}

async function ensureChain() {
  try {
    await iptables(["-t", "nat", "-N", CHAIN]);
  } catch {
    /* chain exists */
  }
  // Ensure PREROUTING jumps to our chain exactly once
  try {
    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
  } catch {
    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
  }
}

/**
 * The real, iptables-backed NatHost — the only implementation production uses.
 * The decision logic it is handed to lives in lib/nat-rules.ts and is tested
 * against an in-memory fake; see the H5 incident note at the top of that file.
 */
function iptablesHost(): NatHost {
  return {
    ensureChain,
    listChain: async () => {
      const { stdout } = await exec("iptables", ["-t", "nat", "-S", CHAIN]);
      return stdout;
    },
    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", CHAIN, ...ruleSpec(r)]),
    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", CHAIN, ...ruleSpec(r)]),
  };
}

/**
 * Reconcile the NXEON_FWD chain with the database, and verify the result.
 *
 * This used to open with `iptables -t nat -F NXEON_FWD` and rebuild the chain in
 * an unguarded loop, so a single failed `-A` aborted the rebuild and left every
 * subsequent server with no DNAT rule — a fleet-wide SSH blackhole that reported
 * DONE, because DONE meant "the last iptables call exited 0" (incident H5).
 *
 * There is no flush now. `reconcileNatChain` reads the chain, applies only the
 * difference, then reads it BACK and throws with the exact missing rules and the
 * command to inspect them if the kernel does not hold what the database says it
 * should. Rules that were already correct are never removed, so no failure in
 * this path can take down a customer who was working before it ran.
 *
 * Throws on an unproven ruleset — callers that cannot tolerate a throw must say
 * so; `remove()` in worker/index.ts calls this after deleting the server row, so
 * a throw there re-queues DELETE onto a row that no longer exists. That caller
 * uses `syncPortForwardsBestEffort` below.
 */
export async function syncPortForwards(): Promise<NatSyncResult> {
  const servers = await db.server.findMany({
    where: {
      ipAddress: { not: null },
      sshPort: { not: null },
      status: { notIn: ["SUSPENDED", "DELETING"] },
    },
    include: { portForwards: true },
  });

  const intent = planNatRules(servers as unknown as ForwardSource[]);

  // Two data problems that used to be invisible because the old loop just built
  // whatever it was handed. Neither blocks the sync — the ruleset we install is
  // still verified end to end — but neither is swallowed either.
  for (const c of intent.conflicts) {
    console.error(
      `[nat] port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
        `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
    );
  }
  for (const r of intent.rejected) {
    console.error(`[nat] ${r.hostname}: no rule installed — ${r.reason}`);
  }

  const result = await reconcileNatChain(iptablesHost(), CHAIN, intent);
  if (result.unparsed.length) {
    console.warn(
      `[nat] ${CHAIN} contains ${result.unparsed.length} rule(s) this engine did not write and ` +
        `will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
    );
  }
  console.log(
    `[nat] ${CHAIN} verified: ${result.verified} rule(s) present (+${result.added} / -${result.deleted})`
  );
  return result;
}

/**
 * For callers that must not be re-queued by a sync failure (server DELETE runs
 * this after the row is gone, so a throw dies on "Server not found" on retry and
 * the sync is never re-attempted — H5's aggravating factor).
 *
 * It still never claims success: the failure is logged in full and returned, so
 * the caller can surface it. What it will not do is convert a networking problem
 * into a stuck job that hides it.
 */
export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
  try {
    await syncPortForwards();
    return null;
  } catch (e: any) {
    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
    return e instanceof Error ? e : new Error(String(e));
  }
}

