export type GuestDiskUsage = { usedBytes: number; totalBytes: number };

/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`). */
export type GuestAgentClient = {
  get: (path: string, params?: Record<string, any>) => Promise<any>;
};

// Pseudo / virtual filesystems that don't represent real on-disk usage and must
// never be picked as the root filesystem. Matched against the fsinfo `type`.
const PSEUDO_FS_TYPES = new Set([
  "squashfs", "tmpfs", "devtmpfs", "overlay", "overlayfs", "vfat", "msdos",
  "proc", "sysfs", "cgroup", "cgroup2", "debugfs", "mqueue", "hugetlbfs",
  "fusectl", "pstore", "autofs", "binfmt_misc", "tracefs", "configfs",
  "securityfs", "ramfs", "nsfs", "efivarfs", "fuse.snapfuse", "iso9660",
]);

/** Is this mountpoint one we should ignore even if the type looks real? */
function isIgnorableMount(mountpoint: string): boolean {
  const mp = String(mountpoint ?? "");
  return (
    mp === "/boot" ||
    mp.startsWith("/boot/") ||
    mp.startsWith("/snap") ||
    mp.startsWith("/var/lib/docker") ||
    mp.startsWith("/run") ||
    mp.startsWith("/dev") ||
    mp.startsWith("/sys") ||
    mp.startsWith("/proc")
  );
}

/**
 * Query the QEMU guest agent's `get-fsinfo` and return the REAL root filesystem
 * usage (the entry mounted at "/", excluding pseudo/boot/loop filesystems).
 *
 * Proxmox RRD's `disk` field is 0 for QEMU VMs — the hypervisor can't see
 * in-guest usage — so this agent call is the only source of real used/total
 * bytes. Best-effort: returns null on any error or when the agent isn't ready
 * (never throws), so a missing agent degrades cleanly to the provisioned-size
 * fallback. In SANDBOX returns a synthetic, gently-varying realistic value.
 *
 * @param sandboxTotalBytes only used to size the synthetic sandbox value.
 */
export async function getGuestDiskUsage(
  client: GuestAgentClient,
  node: string,
  vmid: number,
  sandboxTotalBytes?: number
): Promise<GuestDiskUsage | null> {
  if (SANDBOX) {
    const total = sandboxTotalBytes && sandboxTotalBytes > 0 ? sandboxTotalBytes : 40 * 1024 ** 3;
    const base = 0.3 + (Math.abs(vmid) % 35) / 100; // 0.30..0.64
    const drift = 0.03 * Math.sin(Date.now() / (6 * 3600_000) + vmid); // slow ±3%
    const frac = Math.min(0.95, Math.max(0.05, base + drift));
    return { usedBytes: Math.round(total * frac), totalBytes: total };
  }

  try {
    const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/get-fsinfo`);
    // The agent wraps the array in { result: [...] }; tolerate a bare array too.
    const list: any[] = Array.isArray(res?.result)
      ? res.result
      : Array.isArray(res)
        ? res
        : [];
    if (list.length === 0) return null;

    const real = list.filter((fs) => {
      const type = String(fs?.type ?? "").toLowerCase();
      const mp = String(fs?.mountpoint ?? "");
      if (PSEUDO_FS_TYPES.has(type)) return false;
      if (isIgnorableMount(mp)) return false;
      const total = Number(fs?.["total-bytes"]);
      return Number.isFinite(total) && total > 0;
    });
    if (real.length === 0) return null;

    // Prefer the real root filesystem; otherwise the largest real mount.
    const root =
      real.find((fs) => String(fs?.mountpoint) === "/") ??
      real.sort((a, b) => Number(b?.["total-bytes"]) - Number(a?.["total-bytes"]))[0];

    const usedBytes = Number(root?.["used-bytes"]);
    const totalBytes = Number(root?.["total-bytes"]);
    if (!Number.isFinite(usedBytes) || !Number.isFinite(totalBytes) || totalBytes <= 0) {
      return null;
    }
    return { usedBytes, totalBytes };
  } catch {
    // Agent not installed / not ready / VM stopped / transient PVE error.
    return null;
  }
}

