 *
 * Returns true only on a real reply. On timeout it returns FALSE rather than
 * throwing, so the caller can degrade its message honestly instead of failing a
 * server that is merely slow — a guest with no agent installed is a normal state
 * for some images, and calling that a provisioning failure would be its own lie.
 */
export async function waitForGuestAgent(
  client: GuestAgentClient,
  node: string,
  vmid: number,
  timeoutMs = 180_000,
  pollMs = 5_000
): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      await client.get(`/nodes/${node}/qemu/${vmid}/agent/ping`);
      return true;
    } catch {
      /* agent not up yet */
    }
    if (Date.now() >= deadline) return false;
    await new Promise((r) => setTimeout(r, pollMs));
  }
}

