input.content:
import { GAME_FAMILIES, type GameFamily } from "./games";

/**
 * Game auto-update: the remote script, its output parser, and the verdict.
 *
 * INCIDENT ("Game auto-update cannot fail", honest inventory #3): the old
 * `updateCommand` returned
 *
 *     set -e; <steam>; <restart>; true
 *
 * where the steamcmd call ended `|| true` and was skipped entirely when steamcmd
 * was absent, every restart branch ended `|| true`, and the whole command ended
 * `; true`. The remote command could NOT exit non-zero. So `gameUpdate` always
 * reached its notification and always told the customer *"The latest server
 * update was applied and the service was restarted."* — for a box where steamcmd
 * was not installed, where no matching systemd unit existed, or where the service
 * came back dead. This runs unattended every 6 hours.
 *
 * `worker/apps.ts` is the model this follows: every operation declares what it
 * PROVES, the remote side emits explicit markers, and an exit code of 0 is never
 * accepted as evidence. (`wp_die()` prints its error and exits 0 — that is the
 * lesson, and `|| true` is the same lesson wearing a different hat.)
 *
 * A second honesty problem is fixed here too: minecraft and terraria have no
 * steamcmd app id, so for those families the job never updated ANYTHING — it
 * restarted a service. The success message now says which of the two happened.
 *
 * Pure and dependency-free: no SSH, no clock. Covered by test/game-update.test.ts,
 * which also runs `sh -n` and `dash -n` over the generated script.
 */

/** Steam dedicated-server app IDs for steamcmd-based families. */
export const STEAM_APPID: Partial<Record<GameFamily, string>> = {
  valheim: "896660",
  rust: "258550",
  palworld: "2394010",
  cs2: "730",
};

/** systemd service name candidates per family (first that exists wins). */
export const SERVICE_HINT: Record<GameFamily, string> = {
  minecraft: "minecraft",
  valheim: "valheim",
  rust: "rust",
  palworld: "palworld",
  cs2: "cs2",
  terraria: "terraria",
};

/** Does this family have an update source at all, or is the job only a restart? */
export function updatesFromSteam(family: GameFamily): boolean {
  return Boolean(STEAM_APPID[family]);
}

/** Seconds we wait for the unit to come back before we stop claiming anything. */
export const RESTART_WAIT_TRIES = 30;
export const RESTART_WAIT_SLEEP_S = 2;

/**
 * Build the remote script.
 *
 * Design rules, each of which the old one-liner broke:
 *
 *  - No `set -e` and no trailing `; true`. Control flow is explicit, and the exit
 *    status is irrelevant — the MARKERS are the contract, so a truncated or
 *    dropped connection is detectable (no `NXGU:END`) rather than indistinguishable
 *    from success.
 *  - steamcmd's own exit code is not trusted (it is famously unreliable and
 *    frequently non-zero on a perfectly good update). We match its own success
 *    line instead, and report the code alongside.
 *  - "no unit matched" is an outcome we emit, not a branch we swallow.
 *  - The post-restart state is polled and reported verbatim. `active` is the only
 *    thing that will be called success upstream.
 *
 * `family` is constrained to GAME_FAMILIES by the caller AND re-checked here, so
 * nothing unvalidated is interpolated into the shell.
 */
export function updateCommand(family: GameFamily): string {
  if (!GAME_FAMILIES.includes(family)) throw new Error(`not a game family: ${family}`);
  const appId = STEAM_APPID[family];
  const svc = SERVICE_HINT[family];
  // Both are compile-time constants from the tables above — never customer input.

  const steam = appId
    ? [
        `if command -v steamcmd >/dev/null 2>&1; then`,
        `  out=$(steamcmd +login anonymous +app_update ${appId} validate +quit 2>&1); rc=$?`,
        `  say "STEAM_RC:$rc"`,
        // steamcmd prints "Success! App '<id>' fully installed." or "... already up to date."
        `  if printf '%s' "$out" | grep -q "Success! App '${appId}'"; then`,
        `    say "STEAM:OK"`,
        `  else`,
        `    say "STEAM:FAIL"`,
        `    printf '%s' "$out" | grep -i 'error' | head -3 | while IFS= read -r l; do say "STEAM_ERR:$l"; done`,
        `  fi`,
        `else`,
        `  say "STEAM:ABSENT"`,
        `fi`,
      ].join("\n")
    : `say "STEAM:NA"`;

  return [
    `say() { printf 'NXGU:%s\\n' "$1"; }`,
    // 1. Resolve the unit. `systemctl cat` succeeds only for a unit that exists.
    `unit=""`,
    `for c in ${svc} ${svc}-server; do`,
    `  if systemctl cat "$c" >/dev/null 2>&1; then unit="$c"; break; fi`,
    `done`,
    `if [ -z "$unit" ]; then`,
    `  unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}')`,
    `fi`,
    `if [ -z "$unit" ]; then say "UNIT:NONE"; say "END"; exit 0; fi`,
    `say "UNIT:$unit"`,
    `was=$(systemctl is-active "$unit" 2>/dev/null); say "WAS:${"$"}{was:-unknown}"`,
    // 2. Update the game files, where such a thing exists.
    steam,
    // 3. Restart, and report the real result of the restart call.
    `systemctl restart "$unit" >/dev/null 2>&1; say "RESTART_RC:$?"`,
    // 4. Wait for it to settle. A game server can take a while to open its port,
    //    so "activating" is a distinct answer from "failed" and both are reported.
    `i=0; st=""`,
    `while [ $i -lt ${RESTART_WAIT_TRIES} ]; do`,
    `  st=$(systemctl is-active "$unit" 2>/dev/null)`,
    `  if [ "$st" = "active" ] || [ "$st" = "failed" ]; then break; fi`,
    `  i=$((i+1)); sleep ${RESTART_WAIT_SLEEP_S}`,
    `done`,
    `say "STATE:${"$"}{st:-unknown}"`,
    `say "END"`,
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

export type GameUpdateFacts = {
  /** The systemd unit the script acted on, or null when nothing matched. */
  unit: string | null;
  /** `systemctl is-active` before the restart. */
  wasActive: string;
  /** Exit code of `systemctl restart`, or null when it never ran. */
  restartRc: number | null;
  /** `systemctl is-active` after the restart, settled or timed out. */
  state: string;
  steam: "ok" | "failed" | "absent" | "na" | "unknown";
  steamRc: number | null;
  steamErrors: string[];
  /** Did the script run to completion? No END marker means we know nothing. */
  complete: boolean;
};

export function parseGameUpdateOutput(out: string): GameUpdateFacts {
  const text = String(out ?? "");
  const one = (re: RegExp): string | null => re.exec(text)?.[1] ?? null;

  const steamRaw = one(/^NXGU:STEAM:(\w+)$/m);
  const steam =
    steamRaw === "OK" ? "ok"
    : steamRaw === "FAIL" ? "failed"
    : steamRaw === "ABSENT" ? "absent"
    : steamRaw === "NA" ? "na"
    : "unknown";

  const rc = (re: RegExp): number | null => {
    const v = one(re);
    return v === null ? null : Number(v);
  };

  const unitLine = one(/^NXGU:UNIT:(.+)$/m);
  const steamErrors: string[] = [];
  for (const m of text.matchAll(/^NXGU:STEAM_ERR:(.*)$/gm)) steamErrors.push(m[1].trim());

  return {
    unit: unitLine === null || unitLine === "NONE" ? null : unitLine.trim(),
    wasActive: one(/^NXGU:WAS:(.*)$/m)?.trim() || "unknown",
    restartRc: rc(/^NXGU:RESTART_RC:(-?\d+)$/m),
    state: one(/^NXGU:STATE:(.*)$/m)?.trim() || "unknown",
    steam,
    steamRc: rc(/^NXGU:STEAM_RC:(-?\d+)$/m),
    steamErrors,
    complete: /^NXGU:END$/m.test(text),
  };
}

// ---------------------------------------------------------------------------
// The verdict
// ---------------------------------------------------------------------------

export type GameUpdateVerdict =
  | { ok: true; title: string; body: string }
  | { ok: false; reason: string };

/**
 * Turn observed facts into the one thing the customer is told.
 *
 * Every refusal names the reason AND the command to run, because "update failed"
 * on a game server six hours after the fact is useless without a next step.
 * Every success states precisely what was proven — including, for minecraft and
 * terraria, that no game update took place at all, because there is no update
 * source for those families and saying otherwise was the original lie.
 */
export function judgeGameUpdate(opts: {
  family: GameFamily;
  hostname: string;
  facts: GameUpdateFacts;
}): GameUpdateVerdict {
  const { family, hostname, facts: f } = opts;
  const appId = STEAM_APPID[family];

  if (!f.complete) {
    return {
      ok: false,
      reason:
        `the update script did not run to completion on ${hostname} (no end marker), so nothing about ` +
        `this run can be verified — the connection may have dropped or the command timed out. ` +
        `Nothing is being claimed. Re-run it by hand: systemctl status <your ${family} unit>`,
    };
  }

  if (!f.unit) {
    return {
      ok: false,
      reason:
        `no systemd service for ${family} was found on ${hostname}, so nothing was updated and ` +
        `nothing was restarted. Check what the server actually runs with: ` +
        `systemctl list-units --type=service | grep -i ${family}`,
    };
  }

  if (appId && f.steam === "absent") {
    return {
      ok: false,
      reason:
        `steamcmd is not installed on ${hostname}, so the ${family} game files were NOT updated. ` +
        `Auto-update cannot work on this server until it is present: apt-get install -y steamcmd ` +
        `(or reinstall from the ${family} image).`,
    };
  }

  if (appId && f.steam !== "ok") {
    const detail = f.steamErrors.length ? ` steamcmd said: ${f.steamErrors.slice(0, 3).join(" | ")}` : "";
    return {
      ok: false,
      reason:
        `steamcmd did not report a successful update of app ${appId} on ${hostname} ` +
        `(exit ${f.steamRc ?? "unknown"}), so the game files were not updated and the service was ` +
        `left alone.${detail} Re-run by hand: steamcmd +login anonymous +app_update ${appId} validate +quit`,
    };
  }

  if (f.state !== "active") {
    return {
      ok: false,
      reason:
        `${f.unit} on ${hostname} is "${f.state}" after the restart` +
        (f.restartRc !== null && f.restartRc !== 0 ? ` (systemctl restart exited ${f.restartRc})` : "") +
        `, so your game server is NOT running. It was "${f.wasActive}" before this ran. ` +
        `Diagnose with: systemctl status ${f.unit} ; journalctl -u ${f.unit} -n 50`,
    };
  }

  if (appId) {
    return {
      ok: true,
      title: `${family} updated on ${hostname}`,
      body:
        `steamcmd reported app ${appId} fully installed/up to date, and ${f.unit} is active again ` +
        `(verified with systemctl, not assumed from an exit code).`,
    };
  }

  // No update source exists for this family. Say that, rather than implying one.
  return {
    ok: true,
    title: `${family} server restarted on ${hostname}`,
    body:
      `${f.unit} was restarted and is active again (verified). Note: ${family} has no automatic ` +
      `update source on Nxeon, so this restarted your server — it did not change the game version. ` +
      `Update the server files yourself, then this schedule will pick them up on the next restart.`,
  };
}

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { serverRootPassword } from "../lib/sftp";
import { GAME_FAMILIES, type GameFamily } from "../lib/games";
import {
  judgeGameUpdate,
  parseGameUpdateOutput,
  updateCommand,
  updatesFromSteam,
} from "../lib/game-update-verify";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { Job } from "@prisma/client";

const execFileP = promisify(execFile);

/**
 * Game-server auto-update handlers.
 *
 * `gameUpdate` runs the per-family update over SSH against the server's private
 * IP (the worker can reach vmbr1) and PROVES the outcome before saying anything
 * to the customer. `gameUpdateSweep` finds RUNNING game servers with
 * `autoUpdate=true` and enqueues GAME_UPDATE jobs for them — safe to call
 * periodically (it de-dupes on in-flight jobs).
 *
 * The remote command used to end `; true` with every step `|| true`, so it could
 * not exit non-zero and this handler always fired *"The latest server update was
 * applied and the service was restarted."* — unattended, every 6 hours, whether
 * or not steamcmd existed, a unit matched, or the service came back. The command
 * builder, the output parser and the verdict now live in lib/game-update-verify.ts
 * where they are tested; SSH failure is still a failure, but a clean SSH exit is
 * no longer evidence of anything.
 *
 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire these
 * in there (`GAME_UPDATE: gameUpdate`) and call `gameUpdateSweep()` on a timer.
 */

async function loadGameServer(serverId: string) {
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);
  return server;
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-update] notify failed", e);
  }
}

/**
 * Tell the customer once, not once per retry.
 *
 * The worker retries a failed job three times, and this one runs every six
 * hours; without this, a server whose steamcmd is missing would generate three
 * identical alarms per sweep, forever, and the customer would learn to ignore
 * them — which is the same outcome as not telling them.
 */
async function notifyFailureOnce(userId: string, serverId: string, title: string, body: string, href: string) {
  const since = new Date(Date.now() - 24 * 60 * 60_000);
  const dupe = await db.notification
    .findFirst({ where: { userId, title, createdAt: { gt: since } } })
    .catch(() => null);
  if (dupe) {
    console.error(`[game-update] ${serverId}: ${body} (customer already notified in the last 24h)`);
    return;
  }
  await notify(userId, title, body, href);
}

/** Run the per-family update over SSH and verify the result. */
export async function gameUpdate(job: Job): Promise<void> {
  const server = await loadGameServer(job.serverId!);
  if (SANDBOX) {
    // No VM exists, so nothing can be proven. Say that, rather than simulating a
    // success message the production path is no longer willing to send.
    await notify(
      server.userId,
      `${server.osTemplate.name} auto-update simulated on ${server.hostname} (sandbox)`,
      "Sandbox only — no server was contacted, nothing was updated and nothing was restarted.",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  const family = server.osTemplate.family as GameFamily;
  if (!GAME_FAMILIES.includes(family)) {
    throw new Error(`game update: ${server.hostname} is not a game server`);
  }
  if (server.status !== "RUNNING") throw new Error("game update: server is not running");
  const password = serverRootPassword(server);
  if (!server.ipAddress || !password) {
    throw new Error("game update: server has no IP/password yet");
  }
  const scrub = (s: string): string => (password ? s.split(password).join("***") : s);
  const href = `/dashboard/servers/${server.id}`;

  const remote = updateCommand(family);
  let stdout = "";
  try {
    const r = await execFileP(
      "sshpass",
      [
        "-p",
        password,
        "ssh",
        "-o",
        "StrictHostKeyChecking=no",
        "-o",
        "UserKnownHostsFile=/dev/null",
        "-o",
        "ConnectTimeout=15",
        `root@${server.ipAddress}`,
        remote,
      ],
      { timeout: 600_000, maxBuffer: 4 * 1024 * 1024 }
    );
    stdout = String(r.stdout ?? "");
  } catch (e: any) {
    // A non-zero exit is now possible and meaningful, but the markers may still
    // have been printed before whatever went wrong — keep them and let the
    // verdict decide, rather than discarding evidence.
    stdout = String(e?.stdout ?? "");
    if (!/^NXGU:END$/m.test(stdout)) {
      // execFile embeds the full argv — including `-p <rootPassword>` — into its
      // error message/cmd. Rethrow a sanitized error so the password can never be
      // stored in Job.error (the worker also redacts as a second line of defense).
      const detail = scrub(String(e?.stderr || e?.message || e));
      const reason = `game update failed: ${detail}`;
      await notifyFailureOnce(
        server.userId,
        server.id,
        `${server.osTemplate.name} auto-update FAILED on ${server.hostname}`,
        `We could not reach or run the update on your server, so nothing was updated: ${detail.slice(0, 300)}`,
        href
      );
      throw new Error(reason);
    }
  }

  const facts = parseGameUpdateOutput(scrub(stdout));
  const verdict = judgeGameUpdate({ family, hostname: server.hostname, facts });

  if (!verdict.ok) {
    await notifyFailureOnce(
      server.userId,
      server.id,
      `${server.osTemplate.name} auto-update did not complete on ${server.hostname}`,
      verdict.reason,
      href
    );
    // Failing the job is the point: it puts the reason in Job.error and in the
    // admin job list instead of leaving a green tick over a dead server.
    throw new Error(`game update not verified: ${verdict.reason}`);
  }

  await notify(server.userId, verdict.title, verdict.body, href);
}

/**
 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
 * auto-update and has no job already in flight. Idempotent / safe to call on a
 * timer. Returns nothing; logs a summary.
 */
export async function gameUpdateSweep(): Promise<void> {
  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoUpdate: true,
      osTemplate: { family: { in: [...GAME_FAMILIES] } },
    },
    select: { id: true, hostname: true, osTemplate: { select: { family: true } } },
  });
  if (candidates.length === 0) return;

  let enqueued = 0;
  for (const s of candidates) {
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;
    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
    enqueued++;
  }
  if (enqueued > 0) {
    const restartOnly = candidates.filter((s) => !updatesFromSteam(s.osTemplate.family as GameFamily)).length;
    console.log(
      `[game-update] sweep enqueued ${enqueued} job(s)` +
        (restartOnly > 0 ? ` (${restartOnly} candidate(s) are restart-only families with no update source)` : "")
    );
  }
}

