import { test } from "node:test";
import assert from "node:assert/strict";
import {
  STALE_INTERVAL_MULTIPLE,
  backupScheduleHealth,
  freshBackupProof,
  humanBytes,
  isAutoBackupDue,
} from "../lib/backup-verify.ts";

/**
 * The backup verification gate — the pure decision logic that stands between
 * "the vzdump task returned" and telling a customer they have a restore point.
 *
 * Every case here is the 2026-07-26 rehearsal finding H4 or one of its edges.
 * Deterministic: no Prisma, no Proxmox, no clock — every entry point takes `now`.
 */

const H = 60 * 60_000;
const T0 = Date.parse("2026-07-26T04:00:00.000Z");

/* ------------------------------------------------------------------ *
 * 1. "Last automatic backup: today" while nothing was ever written
 *    Incident H4: `lastAutoBackup` was stamped by the SWEEP when the job row was
 *    ENQUEUED, and written nowhere else. backupCreate gated only the vzdump
 *    task's exit status — it never checked that an archive existed. So vzdump
 *    could fail every night for a month behind a fresh nightly timestamp, the
 *    schedule read as satisfied, and the customer found out at restore time.
 *    Proof is now a volid that was not there before the run and is not empty.
 * ------------------------------------------------------------------ */

const EXISTING = [
  { volid: "backup:backup/vzdump-qemu-102-2026_07_25-04_00_11.vma.zst", vmid: 102, size: 8_500_000_000 },
];

test("a task that returned but wrote no archive is NOT a backup", () => {
  // The exact H4 shape: vzdump "succeeded", storage is unchanged.
  const p = freshBackupProof({ vmid: 102, before: EXISTING, after: EXISTING });
  assert.equal(p.proven, false);
  assert.match(p.reason, /no new archive for VMID 102/);
  assert.match(p.reason, /there is no restore point from this run/);
  assert.match(p.reason, /pvesm list backup --vmid 102/, "every refusal carries a command the operator can run");
});

test("a new, non-empty archive is proof — and the volid is reported, not inferred", () => {
  const after = [
    ...EXISTING,
    { volid: "backup:backup/vzdump-qemu-102-2026_07_26-04_00_09.vma.zst", vmid: 102, size: 8_600_000_000 },
  ];
  const p = freshBackupProof({ vmid: 102, before: EXISTING, after });
  assert.equal(p.proven, true);
  assert.ok(p.proven && p.volid.endsWith("2026_07_26-04_00_09.vma.zst"));
  assert.ok(p.proven && p.sizeBytes === 8_600_000_000);
});

test("a 0-byte archive is refused — an empty file would only fail at restore time", () => {
  const after = [...EXISTING, { volid: "backup:backup/vzdump-qemu-102-2026_07_26.vma.zst", vmid: 102, size: 0 }];
  const p = freshBackupProof({ vmid: 102, before: EXISTING, after });
  assert.equal(p.proven, false);
  assert.match(p.reason, /0 bytes/);
  assert.match(p.reason, /would fail at restore time/);
});

test("an archive with no reported size is refused rather than assumed good", () => {
  // Absence of evidence is not evidence. The house rule is: prefer refusing.
  const after = [...EXISTING, { volid: "backup:backup/vzdump-qemu-102-new.vma.zst", vmid: 102 }];
  const p = freshBackupProof({ vmid: 102, before: EXISTING, after });
  assert.equal(p.proven, false);
  assert.match(p.reason, /reported no size/);
  assert.match(p.reason, /Not recording a backup we cannot prove/);
});

test("another VM's fresh archive is never mistaken for ours", () => {
  // The platform's own nightly run writes archives for every VMID on the box.
  const after = [
    ...EXISTING,
    { volid: "backup:backup/vzdump-qemu-103-2026_07_26-04_00_09.vma.zst", vmid: 103, size: 9_000_000_000 },
  ];
  assert.equal(freshBackupProof({ vmid: 102, before: EXISTING, after }).proven, false);
});

test("membership, not timestamps — a pre-existing archive can never re-prove itself", () => {
  // Deliberately chosen over a ctime window: ctime comes off the hypervisor and
  // the window would come off the worker's clock, so skew between the two would
  // turn the proof back into a guess. Here the only archive is 24h old and its
  // ctime is in the future relative to nothing we consult.
  const stale = [{ volid: "v1", vmid: 7, size: 1234, ctime: 4_102_444_800 }];
  assert.equal(freshBackupProof({ vmid: 7, before: stale, after: stale }).proven, false);
});

test("a truncated stub beside a good archive does not sink the good one", () => {
  const after = [
    { volid: "good", vmid: 9, size: 5_000_000 },
    { volid: "stub", vmid: 9, size: 0 },
  ];
  const p = freshBackupProof({ vmid: 9, before: [], after });
  assert.equal(p.proven, true);
  assert.ok(p.proven && p.volid === "good");
});

/* ------------------------------------------------------------------ *
 * 2. The schedule anchors on the ATTEMPT, never on the success
 *    Dropping the enqueue-time stamp is only half the fix. Anchoring the next
 *    run on the last SUCCESS looks more correct and is a trap: a server whose
 *    backups always fail has no success to anchor to, so it is "due" on every
 *    15-minute sweep pass forever — hammering a sick VM and burying the rest of
 *    the fleet's queue behind it on a strictly serial worker.
 * ------------------------------------------------------------------ */

test("a server that has never been attempted is due immediately", () => {
  assert.equal(isAutoBackupDue({ now: T0, intervalHours: 24, lastAttemptAt: null }), true);
});

test("the cadence is measured from the attempt, even when the attempt failed", () => {
  const attempted = new Date(T0);
  assert.equal(isAutoBackupDue({ now: T0 + 23 * H, intervalHours: 24, lastAttemptAt: attempted }), false);
  assert.equal(isAutoBackupDue({ now: T0 + 24 * H, intervalHours: 24, lastAttemptAt: attempted }), true);
});

test("a schedule with no interval is never due, and cannot divide by zero into a loop", () => {
  assert.equal(isAutoBackupDue({ now: T0, intervalHours: null, lastAttemptAt: null }), false);
  assert.equal(isAutoBackupDue({ now: T0, intervalHours: 0, lastAttemptAt: null }), false);
  assert.equal(isAutoBackupDue({ now: T0, intervalHours: -5, lastAttemptAt: null }), false);
});

/* ------------------------------------------------------------------ *
 * 3. Absence is rendered, not hidden
 *    The panel used to print "Last automatic backup: <date>" or, when the column
 *    was null, "none yet — the first one runs on the next sweep" — which reads
 *    identically on a brand-new server and on one whose backups have failed
 *    thirty nights running. These are different facts and the customer needs to
 *    be able to tell them apart.
 * ------------------------------------------------------------------ */

const base = { now: T0, autoBackup: true, intervalHours: 24 };

test("never attempted reads as pending, and promises nothing", () => {
  const h = backupScheduleHealth({ ...base, lastVerifiedAt: null, lastAttempt: null });
  assert.equal(h.state, "pending");
  assert.match(h.detail, /No automatic backup has run yet/);
});

test("attempted but never verified is called out — this is the H4 customer", () => {
  const h = backupScheduleHealth({
    ...base,
    lastVerifiedAt: null,
    lastAttempt: { at: new Date(T0 - 30 * 24 * H), status: "DONE" },
  });
  assert.equal(h.state, "never");
  assert.match(h.detail, /none has been verified to exist in storage/);
  assert.match(h.detail, /Do not rely on having a restore point/);
  assert.ok(!/none yet/.test(h.detail), "must not read like a fresh server");
});

test("a failed last attempt outranks everything else and says so plainly", () => {
  const h = backupScheduleHealth({
    ...base,
    lastVerifiedAt: new Date(T0 - 12 * H),
    lastAttempt: { at: new Date(T0 - 1 * H), status: "FAILED" },
  });
  assert.equal(h.state, "failing");
  assert.match(h.detail, /FAILED/);
  assert.match(h.detail, /most recent backup we can prove exists is from 2026-07-25 16:00 UTC/);
  assert.match(h.detail, /do not assume tonight's run will fix it/i);
});

test("a verified backup inside the window is the only case that reads reassuring", () => {
  const h = backupScheduleHealth({
    ...base,
    lastVerifiedAt: new Date(T0 - 6 * H),
    lastAttempt: { at: new Date(T0 - 6 * H), status: "DONE" },
  });
  assert.equal(h.state, "ok");
  assert.match(h.detail, /Last verified backup: 2026-07-25 22:00 UTC/);
  assert.match(h.detail, /confirmed present in storage/);
});

test("a verified-but-old backup goes stale rather than staying green", () => {
  // The silent-failure signature: proof exists, but it stopped being renewed.
  const justInside = backupScheduleHealth({
    ...base,
    lastVerifiedAt: new Date(T0 - STALE_INTERVAL_MULTIPLE * 24 * H),
    lastAttempt: null,
  });
  assert.equal(justInside.state, "ok", "exactly at the threshold is not yet stale");

  const past = backupScheduleHealth({
    ...base,
    lastVerifiedAt: new Date(T0 - (STALE_INTERVAL_MULTIPLE * 24 + 1) * H),
    lastAttempt: null,
  });
  assert.equal(past.state, "stale");
  assert.match(past.detail, /not keeping up/);
  assert.match(past.detail, /unprotected/);
});

test("a disabled schedule claims nothing at all", () => {
  assert.equal(backupScheduleHealth({ ...base, autoBackup: false, lastVerifiedAt: null, lastAttempt: null }).state, "off");
  assert.equal(
    backupScheduleHealth({ ...base, intervalHours: null, lastVerifiedAt: new Date(T0), lastAttempt: null }).state,
    "off",
    "enabled with no cadence is not a schedule",
  );
});

test("humanBytes never renders a size that would misreport an archive", () => {
  assert.equal(humanBytes(0), "0 B");
  assert.equal(humanBytes(1024), "1.0 KB");
  assert.equal(humanBytes(8_600_000_000), "8.0 GB");
  assert.equal(humanBytes(Number.NaN), "unknown size");
  assert.equal(humanBytes(-1), "unknown size");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  natFailureMessage,
  natReconcilePlan,
  parseChainRules,
  planNatRules,
  reconcileNatChain,
  ruleKey,
  ruleSpec,
  ruleText,
  verifyNatChain,
  type ForwardSource,
  type NatHost,
  type NatRule,
} from "../lib/nat-rules.ts";

/**
 * The port-forward verification gate — the decision logic that stands between
 * "the last iptables call exited 0" and telling the fleet its SSH works.
 *
 * Incident H5 (2026-07-26 rehearsal): `syncPortForwards` opened with an
 * unconditional `iptables -t nat -F NXEON_FWD` and rebuilt the chain in a loop
 * with no try/catch, no rollback and no read-back. `exec` was
 * `promisify(execFile)`, so ONE failed `-A` rejected and aborted the loop —
 * every server after that point was left with no DNAT rule at all, the job still
 * went DONE, and the dashboard still showed everyone's port.
 *
 * Deterministic: no iptables, no root, no network. `reconcileNatChain` is driven
 * through its `NatHost` seam with an in-memory fake chain.
 */

const CHAIN = "NXEON_FWD";

const SERVERS: ForwardSource[] = [
  {
    serverId: "s1",
    hostname: "alpha",
    ipAddress: "10.20.0.11",
    sshPort: 20111,
    portForwards: [{ protocol: "tcp", publicPort: 25565, guestPort: 25565 }],
  },
  {
    serverId: "s2",
    hostname: "bravo",
    ipAddress: "10.20.0.12",
    sshPort: 20112,
    portForwards: [{ protocol: "udp", publicPort: 27015, guestPort: 27015 }],
  },
];

/**
 * An in-memory NXEON_FWD chain. `fail` lets a test make one specific rule
 * un-addable, which is exactly the condition that used to blackhole the fleet.
 */
function fakeHost(opts: { initial?: NatRule[]; failOn?: (r: NatRule) => string | null } = {}) {
  let rules: NatRule[] = [...(opts.initial ?? [])];
  let extraLines: string[] = [];
  const calls: string[] = [];
  const host: NatHost = {
    ensureChain: async () => {
      calls.push("ensureChain");
    },
    listChain: async () =>
      [`-N ${CHAIN}`, ...rules.map((r) => `-A ${CHAIN} -p ${r.proto} -m ${r.proto} ${ruleText(r).replace(`-p ${r.proto} `, "")}`), ...extraLines].join("\n"),
    addRule: async (r) => {
      const err = opts.failOn?.(r);
      if (err) {
        calls.push(`add-FAIL ${ruleKey(r)}`);
        throw new Error(err);
      }
      calls.push(`add ${ruleKey(r)}`);
      rules.push(r);
    },
    deleteRule: async (r) => {
      calls.push(`del ${ruleKey(r)}`);
      rules = rules.filter((x) => ruleKey(x) !== ruleKey(r));
    },
  };
  return {
    host,
    calls,
    get rules() {
      return rules;
    },
    addRaw(line: string) {
      extraLines.push(line);
    },
  };
}

/* ------------------------------------------------------------------ *
 * 1. Planning: what the chain is supposed to hold
 * ------------------------------------------------------------------ */

test("every server gets its SSH DNAT plus each of its port forwards", () => {
  const intent = planNatRules(SERVERS);
  assert.deepEqual(intent.rules.map(ruleKey), [
    "tcp/20111->10.20.0.11:22",
    "tcp/25565->10.20.0.11:25565",
    "tcp/20112->10.20.0.12:22",
    "udp/27015->10.20.0.12:27015",
  ]);
  assert.equal(intent.conflicts.length, 0);
  assert.equal(intent.rejected.length, 0);
});

test("a malformed row is refused and reported, never turned into a rule", () => {
  // This is the condition that used to abort the rebuild loop mid-flush: an
  // iptables error partway through a chain that had already been emptied.
  const intent = planNatRules([
    { serverId: "x", hostname: "bad-ip", ipAddress: "not-an-ip", sshPort: 20001, portForwards: [] },
    { serverId: "y", hostname: "no-port", ipAddress: "10.20.0.9", sshPort: null, portForwards: [] },
    {
      serverId: "z",
      hostname: "bad-fwd",
      ipAddress: "10.20.0.8",
      sshPort: 20002,
      portForwards: [
        { protocol: "sctp", publicPort: 80, guestPort: 80 },
        { protocol: "tcp", publicPort: 70000, guestPort: 80 },
      ],
    },
  ]);
  assert.deepEqual(intent.rules.map(ruleKey), ["tcp/20002->10.20.0.8:22"], "only the valid rule survives");
  assert.equal(intent.rejected.length, 4);
  assert.match(intent.rejected.find((r) => r.hostname === "bad-ip")!.reason, /not a valid IPv4/);
  assert.match(intent.rejected.find((r) => r.hostname === "no-port")!.reason, /not a valid port/);
  assert.ok(intent.rejected.some((r) => /not tcp or udp/.test(r.reason)));
  assert.ok(intent.rejected.some((r) => /out-of-range port/.test(r.reason)));
});

test("two servers claiming one public port is a reported collision, not a silent hijack", () => {
  // iptables is first-match, so a duplicate quietly sends one customer's traffic
  // into another customer's VM. The old builder installed both without comment.
  const intent = planNatRules([
    { serverId: "a", hostname: "alpha", ipAddress: "10.20.0.11", sshPort: 20111, portForwards: [] },
    { serverId: "b", hostname: "bravo", ipAddress: "10.20.0.12", sshPort: 20111, portForwards: [] },
  ]);
  assert.deepEqual(intent.rules.map(ruleKey), ["tcp/20111->10.20.0.11:22"], "the loser's rule is NOT installed");
  assert.deepEqual(intent.conflicts, [{ proto: "tcp", dport: 20111, winner: "alpha", losers: ["bravo"] }]);
});

test("the same public port on tcp and udp is not a collision", () => {
  const intent = planNatRules([
    {
      serverId: "a",
      hostname: "alpha",
      ipAddress: "10.20.0.11",
      sshPort: 20111,
      portForwards: [
        { protocol: "tcp", publicPort: 27015, guestPort: 27015 },
        { protocol: "udp", publicPort: 27015, guestPort: 27015 },
      ],
    },
  ]);
  assert.equal(intent.conflicts.length, 0);
  assert.equal(intent.rules.length, 3);
});

/* ------------------------------------------------------------------ *
 * 2. Reading the kernel back
 *    `iptables -S` does NOT echo what you passed to `-A`: it inserts `-m tcp`
 *    and normalises option order, so the output has to be parsed rather than
 *    string-compared. Getting this wrong would make every rule look "missing"
 *    and turn a healthy sync into a permanent failure.
 * ------------------------------------------------------------------ */

test("iptables -S output parses back into rules despite the -m tcp it inserts", () => {
  const out = [
    `-N ${CHAIN}`,
    `-A ${CHAIN} -p tcp -m tcp --dport 20111 -j DNAT --to-destination 10.20.0.11:22`,
    `-A ${CHAIN} -p udp -m udp --dport 27015 -j DNAT --to-destination 10.20.0.12:27015`,
    `-A PREROUTING -j ${CHAIN}`,
  ].join("\n");
  const { rules, unparsed } = parseChainRules(CHAIN, out);
  assert.deepEqual(rules.map(ruleKey), ["tcp/20111->10.20.0.11:22", "udp/27015->10.20.0.12:27015"]);
  assert.equal(unparsed.length, 0, "a jump in another chain is not our rule and is not 'unparsed' either");
});

test("a rule we did not write is reported and NEVER deleted", () => {
  // Deleting something we do not understand is how "a stray rule exists" becomes
  // "somebody's forwarding is gone". We do not know enough to make that trade.
  const out = [
    `-A ${CHAIN} -p tcp -m tcp --dport 20111 -j DNAT --to-destination 10.20.0.11:22`,
    `-A ${CHAIN} -p tcp -m multiport --dports 80,443 -j REDIRECT --to-ports 8080`,
    `-A ${CHAIN} -p tcp -m tcp --dport 3000:3010 -j DNAT --to-destination 10.20.0.11:3000`,
  ].join("\n");
  const { rules, unparsed } = parseChainRules(CHAIN, out);
  assert.equal(rules.length, 1);
  assert.equal(unparsed.length, 2, "a REDIRECT and a port RANGE are both outside what this engine manages");
});

test("ruleSpec is the same argv for -A, -D and -C, so a rule can be un-added exactly", () => {
  const r: NatRule = { proto: "tcp", dport: 20111, destIp: "10.20.0.11", destPort: 22 };
  assert.deepEqual(ruleSpec(r), [
    "-p", "tcp", "--dport", "20111", "-j", "DNAT", "--to-destination", "10.20.0.11:22",
  ]);
});

/* ------------------------------------------------------------------ *
 * 3. Reconcile, not flush
 *    A flush is an instant total outage for every customer on the box, and
 *    everything after a mid-rebuild failure stays down forever. The diff must
 *    leave already-correct rules completely untouched.
 * ------------------------------------------------------------------ */

test("a chain that is already correct is not touched at all", () => {
  const intent = planNatRules(SERVERS);
  const plan = natReconcilePlan(intent.rules, intent.rules);
  assert.deepEqual(plan.toAdd, []);
  assert.deepEqual(plan.toDelete, [], "no flush, no churn — and therefore no window with no rule");
});

test("only the difference moves: a re-IP'd server adds one rule and removes one", () => {
  const before = planNatRules(SERVERS).rules;
  const moved = planNatRules([{ ...SERVERS[0], ipAddress: "10.20.0.99" }, SERVERS[1]]).rules;
  const plan = natReconcilePlan(moved, before);
  assert.deepEqual(plan.toAdd.map(ruleKey), ["tcp/20111->10.20.0.99:22", "tcp/25565->10.20.0.99:25565"]);
  assert.deepEqual(plan.toDelete.map(ruleKey), ["tcp/20111->10.20.0.11:22", "tcp/25565->10.20.0.11:25565"]);
  assert.ok(
    !plan.toDelete.some((r) => r.destIp === "10.20.0.12"),
    "the untouched server's rules are never removed — this is the whole fix for H5",
  );
});

test("reconcile brings an empty chain up and proves the result", async () => {
  const f = fakeHost();
  const result = await reconcileNatChain(f.host, CHAIN, planNatRules(SERVERS));
  assert.equal(result.added, 4);
  assert.equal(result.deleted, 0);
  assert.equal(result.verified, 4);
  assert.equal(f.calls[0], "ensureChain");
});

test("deletions run before additions, so a public port can be reassigned in one pass", async () => {
  const stale: NatRule = { proto: "tcp", dport: 20111, destIp: "10.20.0.77", destPort: 22 };
  const f = fakeHost({ initial: [stale] });
  await reconcileNatChain(f.host, CHAIN, planNatRules(SERVERS));
  const delAt = f.calls.findIndex((c) => c.startsWith("del "));
  const addAt = f.calls.findIndex((c) => c.startsWith("add tcp/20111"));
  assert.ok(delAt >= 0 && addAt > delAt, "the old claim on 20111 is released before the new one is made");
});

/* ------------------------------------------------------------------ *
 * 4. One bad rule must not take out everyone after it
 *    This is the exact H5 blackhole: `await` inside an unguarded for-loop, so
 *    the first rejection abandoned every remaining server. Errors are collected
 *    now, and the READ-BACK is what decides the outcome.
 * ------------------------------------------------------------------ */

test("a rule that will not apply does not abandon the servers after it", async () => {
  const f = fakeHost({ failOn: (r) => (r.dport === 20111 ? "iptables: No chain/target/match by that name." : null) });
  await assert.rejects(
    () => reconcileNatChain(f.host, CHAIN, planNatRules(SERVERS)),
    (e: Error) => {
      assert.match(e.message, /1 port-forward rule\(s\) are NOT in the NXEON_FWD chain/);
      assert.match(e.message, /--dport 20111/);
      assert.match(e.message, /iptables -t nat -S NXEON_FWD/, "the operator is told what to run");
      return true;
    },
  );
  // The three healthy servers/forwards are still installed — under the old
  // flush-and-rebuild they would every one of them be gone.
  assert.deepEqual(f.rules.map(ruleKey).sort(), [
    "tcp/20112->10.20.0.12:22",
    "tcp/25565->10.20.0.11:25565",
    "udp/27015->10.20.0.12:27015",
  ]);
});

test("an add that errors but whose rule IS present is not called a failure", async () => {
  // A concurrent sync (two workers, a retried job) can install the rule between
  // our read and our write. iptables then errors, but the ruleset is correct —
  // and the ruleset is what we verify, not the exit codes.
  let attempted = false;
  const f = fakeHost();
  const host: NatHost = {
    ...f.host,
    addRule: async (r) => {
      if (r.dport === 20111 && !attempted) {
        attempted = true;
        await f.host.addRule(r); // it lands anyway
        throw new Error("iptables: Resource temporarily unavailable.");
      }
      return f.host.addRule(r);
    },
  };
  const result = await reconcileNatChain(host, CHAIN, planNatRules(SERVERS));
  assert.equal(result.verified, 4);
});

test("a sync that appears to succeed but leaves the chain wrong still throws", async () => {
  // The defect class in one test: every call "succeeded" and the result is still
  // wrong, so exit codes cannot be the evidence.
  const f = fakeHost();
  const lying: NatHost = { ...f.host, addRule: async () => {} };
  await assert.rejects(
    () => reconcileNatChain(lying, CHAIN, planNatRules(SERVERS)),
    /4 port-forward rule\(s\) are NOT in the NXEON_FWD chain/,
  );
});

test("a stray rule left behind after the sync is also a failure", async () => {
  const orphan: NatRule = { proto: "tcp", dport: 20999, destIp: "10.20.0.44", destPort: 22 };
  const f = fakeHost({ initial: [orphan] });
  const stubborn: NatHost = { ...f.host, deleteRule: async () => {} };
  await assert.rejects(
    () => reconcileNatChain(stubborn, CHAIN, planNatRules(SERVERS)),
    /1 rule\(s\) that should have been removed are still present/,
  );
});

test("unmanaged lines in the chain are surfaced but do not fail the sync", async () => {
  const f = fakeHost();
  f.addRaw(`-A ${CHAIN} -p tcp -m multiport --dports 80,443 -j REDIRECT --to-ports 8080`);
  const result = await reconcileNatChain(f.host, CHAIN, planNatRules(SERVERS));
  assert.equal(result.verified, 4);
  assert.equal(result.unparsed.length, 1);
});

/* ------------------------------------------------------------------ *
 * 5. The sentence the operator actually reads
 * ------------------------------------------------------------------ */

test("verifyNatChain reports both directions of the difference", () => {
  const intended = planNatRules(SERVERS).rules;
  const v = verifyNatChain(intended, [intended[0], { proto: "tcp", dport: 1, destIp: "10.0.0.1", destPort: 1 }]);
  assert.equal(v.ok, false);
  assert.equal(v.missing.length, 3);
  assert.equal(v.extra.length, 1);
  assert.equal(verifyNatChain(intended, [...intended].reverse()).ok, true, "order is not part of correctness here");
});

test("the failure message names the rules, the count and the command — never just 'sync failed'", () => {
  const msg = natFailureMessage({
    chain: CHAIN,
    missing: [{ proto: "tcp", dport: 20111, destIp: "10.20.0.11", destPort: 22 }],
    extra: [],
    errors: ["add -p tcp --dport 20111 ...: iptables: Permission denied"],
  });
  assert.match(msg, /that traffic is being dropped/);
  assert.match(msg, /-p tcp --dport 20111 -j DNAT --to-destination 10\.20\.0\.11:22/);
  assert.match(msg, /Permission denied/);
  assert.match(msg, /iptables -t nat -S NXEON_FWD/);
});

test("a large outage is summarised without dumping the whole fleet into one string", () => {
  const missing = Array.from({ length: 40 }, (_, i) => ({
    proto: "tcp",
    dport: 20000 + i,
    destIp: `10.20.0.${i + 1}`,
    destPort: 22,
  }));
  const msg = natFailureMessage({ chain: CHAIN, missing, extra: [], errors: [] });
  assert.match(msg, /40 port-forward rule\(s\)/);
  assert.match(msg, /\+32 more/);
});

