import { test } from "node:test";
import assert from "node:assert/strict";
import {
  RESTART_WAIT_TRIES,
  STEAM_APPID,
  judgeGameUpdate,
  parseGameUpdateOutput,
  updateCommand,
  updatesFromSteam,
} from "../lib/game-update-verify.ts";
import { GAME_FAMILIES, type GameFamily } from "../lib/games.ts";
import { execFileSync } from "node:child_process";
import { writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

/**
 * The game auto-update verification gate.
 *
 * INCIDENT ("Game auto-update cannot fail"): `updateCommand` returned
 * `set -e; ${steam}${restart}; true` — steamcmd was `|| true` and skipped
 * entirely when absent, every restart branch was `|| true`, and the command
 * ended `; true`. The remote command could NOT exit non-zero, so the handler
 * always fired *"The latest server update was applied and the service was
 * restarted."* This runs unattended every 6 hours.
 *
 * The rule these tests hold: an exit code is never evidence. The remote side
 * emits markers, and only the markers decide what the customer is told.
 * Deterministic: no SSH, no clock.
 */

const HOST = "mc-01";

function facts(over: Partial<ReturnType<typeof parseGameUpdateOutput>> = {}) {
  return {
    unit: "valheim",
    wasActive: "active",
    restartRc: 0,
    state: "active",
    steam: "ok" as const,
    steamRc: 0,
    steamErrors: [] as string[],
    complete: true,
    ...over,
  };
}

/* ------------------------------------------------------------------ *
 * 1. The generated shell must parse on a customer's live server
 *    A quoting mistake in generated shell fails on the box, not in a build.
 *    Same reason test/migration-gate.test.ts runs sh -n / dash -n over
 *    srcInventoryScript.
 * ------------------------------------------------------------------ */

test("every family's remote script parses under sh -n and dash -n", () => {
  for (const family of GAME_FAMILIES) {
    const file = join(tmpdir(), `nxeon-gameupdate-${family}-${process.pid}.sh`);
    try {
      writeFileSync(file, updateCommand(family), "utf8");
      // -n parses without executing: nothing here touches the machine.
      execFileSync("sh", ["-n", file], { stdio: "pipe" });
      execFileSync("dash", ["-n", file], { stdio: "pipe" });
    } finally {
      rmSync(file, { force: true });
    }
  }
});

test("the script can no longer be made to always succeed", () => {
  // Guard on the exact shape of the bug. `|| true` on the operations that decide
  // the outcome, and a trailing `; true`, are what made every run a success.
  for (const family of GAME_FAMILIES) {
    const s = updateCommand(family);
    assert.ok(!/;\s*true\s*$/.test(s.trim()), `${family}: script must not end in an unconditional true`);
    assert.ok(!/systemctl restart[^\n]*\|\|\s*true/.test(s), `${family}: the restart must not be swallowed`);
    assert.ok(!/steamcmd[^\n]*\|\|\s*true/.test(s), `${family}: steamcmd must not be swallowed`);
    assert.ok(!/\bset -e\b/.test(s), `${family}: markers are the contract, not the exit status`);
    assert.match(s, /NXGU:END/, `${family}: must emit a completion marker`);
  }
});

test("only the steam families run steamcmd, and each uses its own app id", () => {
  assert.deepEqual(
    GAME_FAMILIES.filter(updatesFromSteam).slice().sort(),
    ["cs2", "palworld", "rust", "valheim"],
  );
  assert.match(updateCommand("valheim"), /app_update 896660 validate/);
  assert.match(updateCommand("rust"), /app_update 258550 validate/);
  assert.ok(!/steamcmd/.test(updateCommand("minecraft")), "minecraft has no steam app id");
  assert.match(updateCommand("minecraft"), /NXGU:%s/, "…but still reports what it did");
});

test("a failed steam update does not bounce a healthy server for nothing", () => {
  // Restarting after an update that did not happen kicks every connected player
  // off, and would make "the service was restarted" the only true half of a
  // false claim. The script exits before the restart when steamcmd did not win.
  const s = updateCommand("rust");
  const skipAt = s.indexOf('say "SKIPPED_RESTART:1"');
  const restartAt = s.indexOf("systemctl restart");
  assert.ok(skipAt > 0 && restartAt > skipAt, "the early exit precedes the restart");
});

test("nothing customer-controlled is interpolated into the script", () => {
  assert.throws(() => updateCommand("minecraft; rm -rf /" as GameFamily), /not a game family/);
  for (const [family, appId] of Object.entries(STEAM_APPID)) {
    assert.match(String(appId), /^\d+$/, `${family}: app id must be numeric`);
  }
});

/* ------------------------------------------------------------------ *
 * 2. Parsing the markers
 *    Real captured output shapes, including the case where the SSH call itself
 *    failed after the script had already printed most of its evidence.
 * ------------------------------------------------------------------ */

test("a clean steam run parses into the facts the verdict needs", () => {
  const out = [
    "NXGU:UNIT:valheim",
    "NXGU:WAS:active",
    "NXGU:STEAM_RC:0",
    "NXGU:STEAM:OK",
    "NXGU:RESTART_RC:0",
    "NXGU:STATE:active",
    "NXGU:END",
  ].join("\n");
  assert.deepEqual(parseGameUpdateOutput(out), facts());
});

test("steamcmd's own error lines survive into the report", () => {
  const out = [
    "NXGU:UNIT:valheim",
    "NXGU:WAS:active",
    "NXGU:STEAM_RC:8",
    "NXGU:STEAM:FAIL",
    "NXGU:STEAM_ERR:ERROR! Failed to install app '896660' (Disk write failure)",
    "NXGU:SKIPPED_RESTART:1",
    "NXGU:STATE:active",
    "NXGU:END",
  ].join("\n");
  const f = parseGameUpdateOutput(out);
  assert.equal(f.steam, "failed");
  assert.equal(f.steamRc, 8);
  assert.deepEqual(f.steamErrors, ["ERROR! Failed to install app '896660' (Disk write failure)"]);
  assert.equal(f.restartRc, null, "the restart never ran, so there is no code to report");
});

test("no unit found parses as no unit, not as a blank success", () => {
  const f = parseGameUpdateOutput("NXGU:UNIT:NONE\nNXGU:END");
  assert.equal(f.unit, null);
  assert.equal(f.complete, true);
});

test("truncated output is detectable — the missing END marker is the whole point", () => {
  const f = parseGameUpdateOutput("NXGU:UNIT:valheim\nNXGU:WAS:active\nNXGU:STEAM:OK");
  assert.equal(f.complete, false);
});

test("noise around the markers does not confuse the parser", () => {
  // sshd banners, MOTDs and steamcmd's own chatter all land in the same stream.
  const out = [
    "Warning: Permanently added '10.20.0.5' (ED25519) to the list of known hosts.",
    "  Nxeon — Claude Code is pre-installed on this server.",
    "NXGU:UNIT:cs2",
    "Redirecting to /bin/systemctl restart cs2.service",
    "NXGU:WAS:inactive",
    "NXGU:STEAM_RC:0",
    "NXGU:STEAM:OK",
    "NXGU:RESTART_RC:0",
    "NXGU:STATE:active",
    "NXGU:END",
  ].join("\n");
  const f = parseGameUpdateOutput(out);
  assert.equal(f.unit, "cs2");
  assert.equal(f.wasActive, "inactive");
  assert.equal(f.state, "active");
});

/* ------------------------------------------------------------------ *
 * 3. The verdict — what the customer is actually told
 * ------------------------------------------------------------------ */

test("steamcmd not installed is a FAILURE, not a quiet skip", () => {
  // The headline case. steamcmd absent used to mean the steam block was omitted
  // entirely and the customer was told the update had been applied.
  const v = judgeGameUpdate({ family: "valheim", hostname: HOST, facts: facts({ steam: "absent" }) });
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /steamcmd is not installed/.test(v.reason));
  assert.ok(!v.ok && /game files were NOT updated/.test(v.reason));
  assert.ok(!v.ok && /apt-get install -y steamcmd/.test(v.reason), "every refusal carries a command");
});

test("no matching systemd unit is a FAILURE with the command to find out why", () => {
  const v = judgeGameUpdate({ family: "rust", hostname: HOST, facts: facts({ unit: null }) });
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /nothing was updated and nothing was restarted/.test(v.reason));
  assert.ok(!v.ok && /systemctl list-units --type=service \| grep -i rust/.test(v.reason));
});

test("a service that does not come back is a FAILURE, however clean the exit code", () => {
  const v = judgeGameUpdate({
    family: "valheim",
    hostname: HOST,
    facts: facts({ state: "failed", restartRc: 0, wasActive: "active" }),
  });
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /your game server is NOT running/.test(v.reason));
  assert.ok(!v.ok && /It was "active" before this ran/.test(v.reason), "the customer needs to know we broke it");
  assert.ok(!v.ok && /journalctl -u valheim -n 50/.test(v.reason));
});

test("a service still starting after the wait window is not called success", () => {
  // "activating" is honest uncertainty. Prefer refusing over guessing.
  const v = judgeGameUpdate({ family: "cs2", hostname: HOST, facts: facts({ state: "activating" }) });
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /is "activating" after the restart/.test(v.reason));
  assert.ok(RESTART_WAIT_TRIES >= 30, "the window must be generous before we report uncertainty");
});

test("output we never received produces a refusal, not an assumption", () => {
  const v = judgeGameUpdate({ family: "palworld", hostname: HOST, facts: facts({ complete: false }) });
  assert.equal(v.ok, false);
  assert.ok(!v.ok && /did not run to completion/.test(v.reason));
  assert.ok(!v.ok && /Nothing is being claimed/.test(v.reason));
});

test("a proven steam update says exactly what was proven", () => {
  const v = judgeGameUpdate({ family: "valheim", hostname: HOST, facts: facts() });
  assert.equal(v.ok, true);
  assert.ok(v.ok && /app 896660 fully installed\/up to date/.test(v.body));
  assert.ok(v.ok && /verified with systemctl, not assumed from an exit code/.test(v.body));
});

test("minecraft and terraria are told the truth: nothing was updated", () => {
  // Second honesty bug in the same handler. These families have no steamcmd app
  // id, so the job never updated anything — it restarted a service, while the
  // notification said "the latest server update was applied".
  for (const family of ["minecraft", "terraria"] as const) {
    const v = judgeGameUpdate({
      family,
      hostname: HOST,
      facts: facts({ unit: family, steam: "na", steamRc: null }),
    });
    assert.equal(v.ok, true);
    assert.ok(v.ok && v.title.includes("restarted"), `${family}: the title must not claim an update`);
    assert.ok(v.ok && /did not change the game version/.test(v.body));
    assert.ok(v.ok && !/latest server update was applied/.test(v.body));
  }
});

test("the steam gate is checked before the service state, so the real cause is reported first", () => {
  // Both are wrong; the customer needs the cause, not the symptom.
  const v = judgeGameUpdate({
    family: "rust",
    hostname: HOST,
    facts: facts({ steam: "absent", state: "failed" }),
  });
  assert.ok(!v.ok && /steamcmd is not installed/.test(v.reason));
});

