      status: null,
      adoptExpiry: false,
      note:
        `The certificate served for ${domain} covers the right hostname but is NOT trusted by browsers ` +
        `(${served.authorizationError || "chain verification failed"}), so visitors still get a security ` +
        `warning. This is not an active certificate. Check that your web server is serving the full chain ` +
        `(fullchain.pem, not cert.pem).`,
    };
