  const differentDate =
    recordedExpiry !== null && Math.abs(served.notAfter.getTime() - recordedExpiry.getTime()) > DAY_MS;

  if (!ours && differentDate) {
    // The M7 #5 case. Adopting this date is what let the origin certificate die.
    const oursValid = recordedExpiry !== null && recordedExpiry.getTime() > now;
    const issuer = served.issuerO || served.issuerCN || "an unknown issuer";
