      status: oursValid ? "ACTIVE" : "EXPIRED",
      adoptExpiry: false,
      note:
        `The certificate served for ${domain} was issued by ${issuer} and expires ` +
        `${served.notAfter.toISOString().slice(0, 10)} — it is NOT the certificate we issued, which expires ` +
        `${recordedExpiry!.toISOString().slice(0, 10)}. That normally means ${domain} is behind a CDN or ` +
        `proxy (Cloudflare, Fastly) terminating TLS at its edge. We are keeping our own expiry date rather ` +
        `than the edge's, because yours is the one that has to be renewed — if it lapses, the CDN can no ` +
        `longer reach your origin over HTTPS.`,
    };
  }

  if (expiredOnWire) {
    return {
      status: "EXPIRED",
      adoptExpiry: ours,
      note:
        `The certificate being served for ${domain} expired on ${served.notAfter.toISOString().slice(0, 10)}. ` +
        `Visitors see a browser security warning until a new one is installed.`,
    };
  }

  return { status: "ACTIVE", adoptExpiry: ours, note: null };
}

