 * The sentence for a renewal that renewed nothing.
 *
 * Split out and tested because getting it wrong is the whole defect: the old
 * message said "renewed … valid until <the same date as before>", which reads as
 * a successful renewal and is exactly why nobody noticed.
 */
export function unchangedRenewalNote(domain: string, expiresAt: Date, isRenewal: boolean): string {
  const when = expiresAt.toISOString().slice(0, 10);
  return isRenewal
    ? `certbot did not issue a new certificate for ${domain} — it reported the existing one is not yet due ` +
        `for renewal and left it in place, valid until ${when}. Nothing changed. If you believe it IS due, ` +
        `the certificate on disk disagrees with our record and support should force a renewal.`
    : `A certificate for ${domain} already existed and certbot reused it rather than requesting a new one. ` +
        `It is valid until ${when}.`;
