import { test } from "node:test";
import assert from "node:assert/strict";
import {
  classifyCertbotOutcome,
  issuerMatchesOurs,
  servedCertVerdict,
  unchangedRenewalNote,
  type ServedIdentity,
} from "../lib/ssl-verify.ts";

/**
 * The SSL verification gate — what a certbot run and a TLS handshake are allowed
 * to prove.
 *
 * Both cases here are M7 findings from the 2026-07-26 rehearsal. Deterministic:
 * no TLS, no SSH, no certbot, no clock.
 */

const NOW = Date.parse("2026-07-26T00:00:00.000Z");
const DAY = 86_400_000;
const LE = { issuerCN: "R11", issuerO: "Let's Encrypt" };

function served(over: Partial<ServedIdentity> = {}): ServedIdentity {
  return {
    notAfter: new Date(NOW + 60 * DAY),
    coversDomain: true,
    issuerCN: LE.issuerCN,
    issuerO: LE.issuerO,
    authorized: true,
    authorizationError: "",
    ...over,
  };
}

/* ------------------------------------------------------------------ *
 * M7 #6. "SSL certificate renewed … valid until <old date>"
 *   certbot certonly exits 0 and prints "Certificate not yet due for renewal"
 *   when it does NOTHING, and that string sat in the same success alternation as
 *   "Congratulations". readObservedExpiry then re-read the UNCHANGED on-disk
 *   notAfter, issuedAt was stamped `new Date()` anyway, and the customer was
 *   told their certificate had been renewed. Nothing had been.
 * ------------------------------------------------------------------ */

test("'not yet due for renewal' is not a renewal", () => {
  const o = classifyCertbotOutcome(
    0,
    "Certificate not yet due for renewal; no action taken.\nTo renew now, run with --force-renewal",
  );
  assert.equal(o.kind, "unchanged");
});

test("a real issuance is recognised by certbot's own success line, not by exit 0", () => {
  assert.equal(classifyCertbotOutcome(0, "Congratulations! Your certificate and chain have been saved").kind, "issued");
  assert.equal(classifyCertbotOutcome(0, "Successfully received certificate.").kind, "issued");
  assert.equal(classifyCertbotOutcome(0, "Certificate is saved at: /etc/letsencrypt/live/x/fullchain.pem").kind, "issued");
});

test("a forced renewal prints both strings and still counts as issued", () => {
  const o = classifyCertbotOutcome(
    0,
    "Certificate not yet due for renewal, but simulating renewal because --force-renewal.\nCongratulations! …",
  );
  assert.equal(o.kind, "issued", "order matters: issuance evidence wins");
});

test("exit 0 with no recognisable outcome is a FAILURE, never an assumed success", () => {
  assert.equal(classifyCertbotOutcome(0, "").kind, "failed");
  assert.equal(classifyCertbotOutcome(0, "some unfamiliar certbot output").kind, "failed");
});

test("an unknown exit status is not success — ssh2 reports null when the channel just closed", () => {
  assert.equal(classifyCertbotOutcome(null, "Congratulations!").kind, "failed");
  assert.equal(classifyCertbotOutcome(1, "Congratulations!").kind, "failed");
});

test("the no-op message says nothing changed, and never uses the word renewed as an outcome", () => {
  const msg = unchangedRenewalNote("shop.example.com", new Date(Date.parse("2026-10-01T00:00:00Z")), true);
  assert.match(msg, /did not issue a new certificate/);
  assert.match(msg, /Nothing changed/);
  assert.match(msg, /2026-10-01/);
  assert.ok(!/^SSL certificate renewed/.test(msg));
});

/* ------------------------------------------------------------------ *
 * M7 #5. The probe adopted a CDN edge certificate's expiry as our own
 *   `probeServedCertificate` used rejectUnauthorized:false and then checked only
 *   name-match and a future notAfter — never socket.authorized, never the
