 *   publicly trusted and covers the domain, and verifyServed overwrote
 *   expiresAt with the edge's date. The origin's real certificate therefore
 *   never looked due, was never renewed, and died silently.
 * ------------------------------------------------------------------ */

const OURS = new Date(NOW + 20 * DAY);

test("a Cloudflare edge certificate never overwrites our origin's expiry", () => {
  const v = servedCertVerdict({
    domain: "shop.example.com",
    served: served({ issuerCN: "WE1", issuerO: "Google Trust Services", notAfter: new Date(NOW + 300 * DAY) }),
    recordedExpiry: OURS,
    ourIssuer: "letsencrypt",
    now: NOW,
  });
  assert.equal(v.adoptExpiry, false, "this single flag is the whole fix");
  assert.equal(v.status, "ACTIVE", "our own certificate is still valid, so the row is not wrong");
  assert.match(v.note!, /NOT the certificate we issued/);
  assert.match(v.note!, /Google Trust Services/);
  assert.match(v.note!, /behind a CDN or proxy/);
  assert.match(v.note!, /2026-08-15/, "our date, not the edge's, is the one that matters");
});

test("behind a CDN, an origin certificate that has already lapsed is reported EXPIRED", () => {
  // The exact outcome the old code could never reach: the edge is happily
  // serving 200s while the origin certificate is dead.
