    domain: "shop.example.com",
    served: served({ issuerCN: "WE1", issuerO: "Google Trust Services", notAfter: new Date(NOW + 300 * DAY) }),
    recordedExpiry: new Date(NOW - DAY),
    ourIssuer: "letsencrypt",
    now: NOW,
  });
  assert.equal(v.status, "EXPIRED");
  assert.equal(v.adoptExpiry, false);
});

