  // renewal we did not perform, and adopting it avoids a pointless reissue.
  const v = servedCertVerdict({
    domain: "shop.example.com",
    served: served({ notAfter: new Date(NOW + 89 * DAY) }),
    recordedExpiry: OURS,
    ourIssuer: "letsencrypt",
    now: NOW,
  });
  assert.equal(v.adoptExpiry, true);
  assert.equal(v.status, "ACTIVE");
