  const v = servedCertVerdict({
    domain: "shop.example.com",
    served: served({ notAfter: new Date(NOW - DAY), authorized: false, authorizationError: "CERT_HAS_EXPIRED" }),
    recordedExpiry: new Date(NOW - DAY),
    ourIssuer: "letsencrypt",
