import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import { decryptSecret } from "../lib/crypto-box";
import {
  withServerSsh,
  exec,
  execInput,
  assertIdent,
  assert,
  shellQuote,
  pkgInstallPrefix,
  SETUP_TIMEOUT_MS,
  INSTALL_TIMEOUT_MS,
  QUICK_TIMEOUT_MS,
} from "../lib/ssh-exec";
import type { Job } from "@prisma/client";
import type { Client } from "ssh2";

/**
 * Control-panel DB_CREATE / DB_DELETE handlers (MySQL/MariaDB & PostgreSQL).
 *
 * Registered in worker/index.ts:
 *   DB_CREATE: dbCreate,
 *   DB_DELETE: dbDelete,
 *
 * The generated DB password is decrypted IN MEMORY from `passwordEnc`, applied
 * via the DB client's STDIN (never an argv token — mirrors migrate-real.ts), and
 * then `passwordEnc` is CLEARED. Engine is installed on first use.
 *
 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — status flips to ACTIVE and the
 * secret is scrubbed, exactly like the rest of the platform.
 */

const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[cpanel/db] notify failed", e);
  }
}

