// probes below are the same idea for both engines.
//
// The password never reaches argv. It is streamed over STDIN into a 0600 file
// written and deleted by the same shell — a defaults-extra-file for MySQL, a
// .pgpass for PostgreSQL — so it cannot appear in `ps`, in the shell history, or
// in an error message containing the command line.

/** Log in AS the customer's MySQL user and run a trivial query. */
async function proveMysqlLogin(conn: Client, name: string, user: string, password: string): Promise<void> {
  const check = await execInput(
    conn,
    `umask 077; f=$(mktemp) && cat > "$f" && ` +
      `mysql --defaults-extra-file="$f" --protocol=socket -N -B -e 'SELECT 1' ${shellQuote(name)} >/dev/null 2>&1; ` +
      `rc=$?; rm -f "$f"; exit $rc`,
    `[client]\\nuser=${user}\\npassword=${password}\\n`,
    SETUP_TIMEOUT_MS
  );
  if (check.code !== 0) {
    throw new Error(
      `the database was created but the generated credentials did not work when tested — ` +
        `not handing you a password that does not log in. Nothing usable was left behind; ` +
        `delete this database and create it again.`
    );
  }
}

/**
 * Log in AS the customer's PostgreSQL role over TCP.
 *
 * TCP rather than the local socket on purpose: peer authentication on the unix
 * socket would succeed for the wrong reason (it authenticates the OS user, not
 * the password), which would make this probe prove nothing. `.pgpass` is
 * colon-and-backslash delimited, which is why assertInertSecret runs first.
 */
async function provePostgresLogin(conn: Client, name: string, user: string, password: string): Promise<void> {
  const check = await execInput(
    conn,
    `umask 077; f=$(mktemp) && cat > "$f" && ` +
      `PGPASSFILE="$f" psql -h 127.0.0.1 -U ${shellQuote(user)} -d ${shellQuote(name)} -tAc 'SELECT 1' >/dev/null 2>&1; ` +
      `rc=$?; rm -f "$f"; exit $rc`,
    `127.0.0.1:5432:${name}:${user}:${password}\\n`,
    SETUP_TIMEOUT_MS
  );
  if (check.code !== 0) {
    throw new Error(
      `the database was created but the generated credentials did not work when tested over TCP — ` +
        `not handing you a password that does not log in. If your server's pg_hba.conf does not allow ` +
        `password auth on 127.0.0.1, fix that first; delete this database and create it again.`
    );
  }
}

